  "roles": {
    "mouth": { "lit": true, "names": ["the forecourt"], "scenes": ["A forecourt of standing stones faces the sunrise, curving in to the mound's high end. Between the two tallest is the door, a low black square under a lintel of one stone."] },
    "passage": { "names": ["the long passage"], "scenes": ["A passage of upright slabs runs into the mound, roofed with stones laid across, so low you go bent. The slabs are cut with spirals and with lines that might be roads."] },
    "chamber": { "names": ["the cross-chamber"], "scenes": ["The passage opens into a chamber shaped like a cross, its roof rising in stones laid each a little further in than the one below until one stone closes it. Basins of stone stand in the arms, with ash in them."] },
    "recess": { "names": ["a side recess", "the north recess", "the south recess"], "scenes": ["A recess off the chamber, with a basin of stone in it and the burned bones of the first-laid heaped in the basin, a bead or two among them.", "A recess where the slabs are carved closer than anywhere else, all with the same sign: an eye, or a sun, or a door."] },
    "vent": { "lit": true, "names": ["the light-box"], "scenes": ["A slot in the stones over the door, a box of slabs open to the sky at one end: on one morning of the year the sun comes through it and down the whole length of the passage. It is wide enough for a body to squeeze through."] },
    "robbers": { "names": ["the robbers' camp"], "scenes": ["Under the overhang of the forecourt someone has camped: a hearth of three stones, a bundle of picks, a sack with the bottom cut out."] },
    "back_stone": { "names": ["the back-stone"], "scenes": ["The chamber's far arm ends in a single stone taller than the rest, smooth, uncarved; behind it, where it does not quite meet the wall, a draught comes up from below. A portal stone hangs in a slot in the rock beside it."] },
    "stair_foot": { "names": ["the foot of the stair"], "scenes": ["The stair comes down into a low hall cut in the chalk under the mound, white walls gone grey with the smoke of lamps long out. Niches run away along both walls in rows."] },
    "bone_hall": { "names": ["the hall of the bones"], "scenes": ["A long hall of niches, every niche with its dead in it, laid on their sides with their knees drawn up as if asleep, a pot by each head. The floor is swept, as if someone had swept it."] },
    "mourners": { "names": ["the mourners' hall"], "scenes": ["A hall with a hearth and benches cut in the chalk, where the living sat with the dead the night before a burial. Bone flutes hang on pegs along the wall, a whole row of them, long silent."] },
    "ossuary": { "names": ["the ossuary"], "scenes": ["Bones stacked in walls: skulls in rows between courses of long bones, built up to the roof like masonry. In one place the wall has fallen, and someone has dug through behind it."] },
    "gallery": { "names": ["the long gallery"], "scenes": ["A gallery runs on under the halls, its walls painted with people walking all one way, toward the end of it, each carrying something: a pot, a child, a flute, a light."] },
    "embalmers": { "names": ["the embalmers' room"], "scenes": ["A room of stone tables and stone basins, where the dead were made ready. Jars stand in niches, sealed with clay and marked, and the air still smells faintly of resin."] },
    "well": { "names": ["the well of offerings"], "scenes": ["A shaft drops away in the floor, ringed with a low kerb worn smooth by hands. Far down, something white catches your light: what was thrown in."] },
    "kings_door": { "names": ["the king's door"], "scenes": ["The gallery ends at a door: two posts and a lintel of single stones, carved closer than anything else in the halls, round a black opening as tall as a man."] },
    "antechamber": { "names": ["the antechamber"], "scenes": ["Beyond the door the chalk gives way to old dark rock. A small chamber, empty but for a stone bench and the marks of the many who have knelt before it."] },
    "treasury": { "names": ["the king's treasury"], "scenes": ["A low room of stone shelves, most of them bare now. On the floor, a rotted sack, a pick, and a man's bones lie where the robbers' tunnel comes through the wall."] },
    "heart": { "names": ["the king's hall"], "scenes": ["The grave of the first king is a hall, not a grave: a ring of standing stones under the rock, and in the middle of the ring a bier of stone, with a cloak gone to dust on it in the shape of whoever lay there."] },
    "deep_grave": { "names": ["the deep grave"], "scenes": ["Behind the ring a pit goes down into the rock, its sides smooth, and a smell comes up out of it like turned earth. Whatever lies at the bottom of it is not the king, or is not only the king."] }
  },
