    "pilgrim": {
      "knows": { "of": "faith", "label": "Ask {name} about the gods of this country",
        "says": "'This country keeps {god}, mostly: {title}. But every shrine keeps its own god too, and they do not all agree with one another.' {name} speaks more quietly. 'The oldest holy place is not a shrine at all. {holy}, in {where}. Folk say it was holy before there were folk.'" },
