data/generation/scenes/snares.json:
{
  "about": "How each of Orsino's trap mechanisms (orsino-world.json) is understood and dealt with in a generated work: what is noticed of it in passing (sign), what looking closely at it shows (seen), and the ways of making it safe, each with what it needs. Written by hand: Orsino gives a trap's mechanism and what it does, not how it is found out or got past.",
  "mechanisms": {
    "pressure plate": {
      "sign": "One flag of the floor across the way is not quite level with the others, and there is no dust in the crack round it.",
      "seen": "One flag of the floor sits a finger's breadth proud of the rest, with no dust in the crack round it. A foot's weight on it would set off whatever it is joined to; so would any weight.",
      "ways": [
        { "id": "spring", "label": "Lean on the plate with the pole, standing well back", "needing": "pole", "to": "sprung" },
        { "id": "wedge", "label": "Wedge the plate so it cannot sink", "needing": "trapwork", "to": "made_safe" }
      ]
    },
    "tripwire": {
      "sign": "Something catches the light low across the way: a wire, at the height of an ankle.",
      "seen": "The wire runs from a peg at one side to a hole in the stone at the other. Whatever it works is behind the hole. Pull it, or catch a foot in it, and it goes.",
      "ways": [
        { "id": "spring", "label": "Hook the wire with the pole and pull, from well back", "needing": "pole", "to": "sprung" },
        { "id": "pin", "label": "Pin the wire slack against the floor and step over it", "needing": "trapwork", "to": "made_safe" }
      ]
    },
    "hidden switch": {
      "sign": "The wall here is carved all over, and the carving is thickest where the way is narrowest.",
      "seen": "Among the carvings is one that is not carved but set in, a boss that would go in under a hand. It sits where a hand leaning on the wall would find it, at the narrowest place.",
      "ways": [
        { "id": "spring", "label": "Push the switch in with the pole's end, standing clear", "needing": "pole", "to": "sprung" },
        { "id": "wedge", "label": "Wedge the switch so it cannot go in", "needing": "trapwork", "to": "made_safe" }
      ]
    },
    "arcane glyph": {
      "sign": "A glyph is cut in the wall beside the way, and it shimmers faintly, as if it had only just been written.",
      "seen": "The glyph is a word, written to be read by whoever passes it; reading it is what sets it off. Someone who knew the letters could unsay it.",
      "ways": [
        { "id": "unsay", "label": "Unsay the glyph, letter by letter", "needing": "lore", "to": "made_safe" },
        { "id": "spring", "label": "Hold the pole's end across the glyph, looking away", "needing": "pole", "to": "sprung" }
      ]
    },
    "magical rune": {
      "sign": "A rune is laid in the floor across the way, its lines lit with a dull glow that comes and goes, slow as breathing.",
      "seen": "The rune is laid in the floor where a foot must cross it. It is waiting for weight, or warmth; it cannot tell the one from the other.",
      "ways": [
        { "id": "unsay", "label": "Break the rune's lines with the right words", "needing": "lore", "to": "made_safe" },
        { "id": "spring", "label": "Lay the pole's end on the rune from as far off as it allows", "needing": "pole", "to": "sprung" }
      ]
    },
    "enchanted object": {
      "sign": "Something stands in the way that has no business there: an ordinary-looking thing that hums when you come near it.",
      "seen": "The thing is set exactly where anyone going through must brush against it. Whatever is in it wants touching; it would go off for a stick as well as a hand.",
      "ways": [
        { "id": "spring", "label": "Knock it over with the pole, from well back", "needing": "pole", "to": "sprung" },
        { "id": "unsay", "label": "Say over it what quiets such things", "needing": "lore", "to": "made_safe" }
      ]
    }
  }
}

data/generation/scenes/wilds.json:
{
  "about": "Wild country as places on the ground: for each kind of country, the landmarks a stretch of it holds (where it is crossed by water, high ground, and the places people have used), the trails between them, the way in from a road or a settlement, and what it is like to be lost in it. A landmark with a view can be climbed to learn the lie of the land; one with water can be followed.",
  "wood": {
    "trails": ["a holloway between banks of root", "a woodmen's track", "a deer-path", "a green ride between the trees", "a carters' track, soft with leaf"],
    "into": "the path into {zone}",
    "entry": { "name": "the edge of {zone} by {from}", "scene": "Here {zone} begins: hazel and thorn at first, then oak, and the light under them goes green. {from} is behind you, out in the open." },
    "lost": { "name": "somewhere in {zone}", "scene": "Somewhere in {zone}. The trees are all alike in every direction, and the light gives no hint which way is which.", "astray": "The trees close in, and the path you were following is not there any more. You have no idea which way you have come.", "guided": "{?m} stops, looks up at the light coming through the leaves, and turns you a quarter round. 'This way.' And it is." },
    "landmarks": [
      { "id": "charcoal", "name": "the charcoal-burners' clearing", "scene": "A clearing where charcoal has been burned for years: rings of black earth, a turf hut with its door off, cordwood stacked under bark. The smell of old smoke hangs over all of it.", "ambience": "A woodpecker is at work somewhere close." },
      { "id": "oak", "name": "the great oak", "view": true, "scene": "An oak stands in a clearing of its own, too broad for three people to circle with their arms. Its lowest limbs would roof a cart, and the bark is worn smooth where climbers have gone up.", "ambience": "Jays scold from somewhere in the crown." },
      { "id": "spring", "name": "the spring under the beeches", "scene": "Water comes out of a mossy bank under old beeches and runs away in a channel lined with stones. Someone set those stones; someone hung the rag on the branch above.", "ambience": "A wren goes in and out of the bank by the water." },
      { "id": "holly", "name": "the holly hollow", "scene": "A hollow full of holly, dark even at noon, the ground dry underneath and littered with prickled leaves. A good place to keep out of the rain, and to keep out of sight.", "ambience": "Something small rustles away under the holly." },
      { "id": "bank", "name": "the old bank", "scene": "A long bank and ditch run through the wood, grown over with trees as old as any around them. Somebody dug it to mark something, long before anyone now living.", "ambience": "A badger's path runs along the top of the bank." },
      { "id": "windfall", "name": "the windfall", "scene": "A storm has had a row of beeches down: they lie where they fell, roots in the air, and the light comes in where they stood. Bramble has already taken the gap.", "ambience": "Bees are busy in the bramble." },
      { "id": "pollards", "name": "the pollards", "scene": "Ancient pollarded oaks stand about a glade, each one hollow, each with a crown of straight poles cut and grown again for longer than the wood has had its name.", "ambience": "An owl sits in one of the hollows, and does not move." }
    ],
    "water": [
      { "id": "ford", "name": "the ford over the {river}", "scene": "The {river} comes through the wood here over gravel and is shallow enough to wade. Deer have trodden the banks to mud.", "ambience": "A kingfisher goes downstream like a thrown stone." },
      { "id": "footbridge", "name": "the footbridge over the {river}", "scene": "A single split trunk lies across the {river} where the banks are steep, with a rail of one pole. The water underneath is deep and brown.", "ambience": "Trout hang in the shadow of the bridge." }
    ],
    "view": { "change": "Climb up and look out over {zone}", "seen": "From up there the wood is a roof of green, and you can see where everything lies: the clearings, the line of the water, the road beyond the trees.", "unseen": "The lowest limb is within reach." }
  },
  "fen": {
    "trails": ["a line of stakes", "a plank-way over the ooze", "a reed-cutters' path", "a causeway of brushwood", "a dyke-top path"],
    "into": "the stakes out into {zone}",
    "entry": { "name": "the edge of {zone} by {from}", "scene": "Where the fields end, {zone} begins: black water between tussocks, reed higher than your head, and the smell of it. {from} is behind you, on the firm ground." },
    "lost": { "name": "somewhere in {zone}", "scene": "Somewhere out in {zone}. Reed on every side, higher than your head, and water between. Every channel looks like the last.", "astray": "The stakes give out, and the reed closes behind you. You cannot see the firm ground in any direction, nor tell which way it lies.", "guided": "{?m} tests the ground ahead with a pole, frowns, and tries again a yard over. 'Here. Step where I step.' You come out where you meant to." },
    "landmarks": [
      { "id": "eelhut", "name": "the eel-catcher's hut", "scene": "A hut of reed and black timber stands on stilts over the water, with eel-traps of woven willow stacked on its platform. The ladder is pulled up.", "ambience": "Something slides off the bank into the water." },
      { "id": "decoy", "name": "the duck decoy", "scene": "A pool with curving arms of netting going off it into the reed: a decoy for ducks, the screens of reed still standing, the nets rotted in the water.", "ambience": "Duck get up off the pool all at once with a noise like applause." },
      { "id": "alders", "name": "the alder island", "view": true, "scene": "A low island of firm ground stands up out of the fen, crowded with alders and one tall willow. From its top you could see over the reed.", "ambience": "A heron stands at the island's edge and does not trouble to move." },
      { "id": "mere", "name": "the mere", "scene": "Open water: a mere ringed with reed, so still it holds the sky. Old stakes stand in a line out into it and stop, as if a path had once gone further.", "ambience": "A grebe dives and comes up a long way off." },
      { "id": "sluice", "name": "the broken sluice", "scene": "A sluice of squared timbers stands half in the water, its gate gone, a channel running straight as a rule away from it into the reed. Somebody drained this fen once, or meant to.", "ambience": "Water talks in the broken gate." },
      { "id": "staithe", "name": "the reed staithe", "scene": "A landing of piled faggots where the reed-cutters bring their bundles out. Cut reed is stacked here in ricks, waiting for a boat.", "ambience": "Reed-buntings sit on the ricks." }
    ],
    "water": [
      { "id": "ford", "name": "the ford of the {river}", "scene": "The {river} spreads out slow and brown through the fen, and a line of stones lets you cross it, if you are careful where you put your feet.", "ambience": "Eels move under the stones." },
      { "id": "punt", "name": "the punt-crossing of the {river}", "scene": "A flat-bottomed punt is tied to a post on this bank of the {river}, with a rope running across to the far side to pull it by.", "ambience": "The rope creaks as the current leans on the punt." }
    ],
    "view": { "change": "Climb the willow and look out over {zone}", "seen": "From the willow you can see over the reed: the channels, the open water, the line of firm ground, and which way it all goes.", "unseen": "The willow's lowest fork is shoulder-high." }
  },
  "heath": {
    "trails": ["an old drove-way", "a sheep-trod through the heather", "a peat-road", "a line of marker posts"],
    "into": "the track up onto {zone}",
    "entry": { "name": "the foot of {zone} by {from}", "scene": "The fields give way to heather and gorse, and the land rises to the moor. {from} is behind you and below." },
    "lost": { "name": "somewhere on {zone}", "scene": "Somewhere on {zone}. Heather in every direction, the same low hummocks, and a sky with no sun in it to steer by.", "astray": "The trod you were following thins to nothing in the heather. Every rise looks like the last, and the mist has the far ones.", "guided": "{?m} kneels to see which way the heather lies, then stands and points. 'That way.' It is." },
    "landmarks": [
      { "id": "cairn", "name": "the cairn", "view": true, "scene": "A cairn of grey stones stands on the highest ground, taller than a man, every traveller's stone added to it. You can see a long way from here.", "ambience": "A curlew calls, a long way off." },
      { "id": "stone", "name": "the leaning stone", "scene": "A single standing stone, taller than a rider, leans out of the heather as if it were listening. The ground at its foot is bare, as though something walks round it.", "ambience": "Wind hums on the edge of the stone." },
      { "id": "bothy", "name": "the shepherds' bothy", "scene": "A bothy of piled stone and turf, roofed with heather, with a fold for sheep against its back wall. The ashes in its hearth are not very old.", "ambience": "A wheatear flits from the wall to the fold and back." },
      { "id": "peat", "name": "the peat cuttings", "scene": "The moor has been cut away in long black steps, and the peats stand drying in little stacks of three, row after row. Water lies in the bottom of the cuttings.", "ambience": "Bog-cotton nods along the edge of the cuttings." },
      { "id": "dewpond", "name": "the dewpond", "scene": "A round pond lined with clay lies in a hollow of the moor, with no stream to fill it. The sheep come to it from miles, and the mud round it is printed all over.", "ambience": "Skylarks go up and up over the pond." }
    ],
    "water": [
      { "id": "ford", "name": "the ford of the {river}", "scene": "The {river} runs brown off the peat between banks of heather, shallow over flat stones.", "ambience": "A dipper bobs on a stone in the stream." }
    ],
    "view": { "change": "Climb the cairn and look out over {zone}", "seen": "From the top of the cairn the moor lies open all round: the trods, the streams, the far edge where the fields begin.", "unseen": "The stones of the cairn make a rough stair." }
  },
  "fell": {
    "trails": ["a sheep-trod along the fellside", "a cairned path", "a scree path", "a wall-side track"],
    "into": "the path up onto {zone}",
    "entry": { "name": "the foot of {zone} by {from}", "scene": "The ground steepens. Walls run up the fellside and give out where the bracken begins. {from} is behind you, in the valley." },
    "lost": { "name": "somewhere on {zone}", "scene": "Somewhere on {zone}. Rock and scree and cloud, and the ground falling away on more sides than one.", "astray": "The cloud comes down, and with it the end of the path. Every way you turn the ground falls away into grey.", "guided": "{?m} watches the cloud a while, picks out a wall running down the fellside, and follows it. It brings you where you meant to go." },
    "landmarks": [
      { "id": "tarn", "name": "the tarn", "scene": "A tarn lies in a hollow under a crag, so dark it looks bottomless, with a little beach of grey gravel at one end. The wind falls silent here.", "ambience": "A raven croaks from the crag above." },
      { "id": "fold", "name": "the sheepfold", "scene": "A round fold of dry-stone walling stands on a shelf of the fell, its gate a hurdle tied with twine. Sheep have been in it lately.", "ambience": "Sheep on the slope above stop chewing to look at you." },
      { "id": "crag", "name": "the crag", "view": true, "scene": "A crag stands out of the fellside like a broken tooth, with a ledge you could stand on and a long fall below it. From the top you would see the whole valley.", "ambience": "Ravens tumble in the wind under the crag." },
      { "id": "shieling", "name": "the shieling", "scene": "Two huts of stone and turf stand by a beck on a green shelf of the fell, where cattle are brought up in summer. One still has its roof.", "ambience": "The beck chatters past the huts." },
      { "id": "col", "name": "the col", "scene": "A saddle of bare ground between two summits, where the wind comes through hard and the ground is worn to the rock. A cairn marks the way down either side.", "ambience": "The wind never stops." }
    ],
    "water": [
      { "id": "ford", "name": "the stepping-stones over the {river}", "scene": "The {river} comes down off the fell here in a white rush, and someone has set stepping-stones across where it runs widest.", "ambience": "Spray hangs over the stones." }
    ],
    "view": { "change": "Climb the crag and look out over {zone}", "seen": "From the top of the crag the whole of {zone} is laid out: the paths, the becks, the folds, and the valley road below.", "unseen": "A crack runs up the crag that a careful climber could use." }
  }
}

