    },
    {
      "id": "hold",
      "when": {
        "hold": "cave"
      },
      "bundle": "cave/module.json",
      "imports": {
        "party": "@party",
        "land": "@region",
        "outside": "?approach"
      }
    },
    {
      "id": "folk",
      "when": {
        "folk": "hobs"
      },
      "bundle": "hobs/module.json",
      "imports": {
        "party": "@party",
        "outside": "?approach",
        "road": "?road",
        "gate": "hold.gate",
        "yard": "hold.yard",
        "hall": "hold.hall",
        "den": "hold.den",
        "pens": "hold.pens",
        "store": "hold.store",
        "lookout": "hold.lookout",
        "bolt": "hold.bolt",
        "chest": "hold.chest",
        "heap": "hold.heap",
        "backway_known": "hold.backway_known",
        "town": "?prey",
        "chapel": "?chapel"
      }
    },
    {
      "id": "folk",
      "when": {
        "folk": "outlaws"
      },
