data/kits/toll-road/customs/keepers.kyr:
Module toll_customs "Customs-men on the road" {
  Description "A lord's customs-men, keeping his toll on the road: a small fee, collected by right, and the law behind it. They pay for their bread at the inn, and take a cartload at a time, so there is less for everyone else. Run their toll or raise a hand to them, and the settlement they answer to will not serve you.".
  Entity party: group "Your company".
  Place post "The road they keep" is room.
  Place market "The settlement they answer to" is room.
  Entity provider: group "Who sells them bread".

  Person chief "the toll-reeve" at post {
    Role "the lord's toll-reeve". Ancestry human. Calling warrior. Level 2.
    State watching "A man in a good grey coat sits at a trestle by a bar across the road, with a ledger and a strongbox.".
  }
  Person keepers "the customs-men" at post {
    Role "the lord's customs-men". Ancestry human. Calling warrior. Level 1. Numbers 2.
    Called "Fenn", "Garrick".
    Uses go, assail. Plans 6 steps.
    State idle "Two men in the lord's livery lean on the bar across the road.".
  }
  Initially Assert serves(keepers, chief). Initially Assert holds(chief, post). Initially Assert posts(keepers, chief).
  Initially Assert tolls(keepers, post).
  Initially Set quantity(chief, rations) to 4.

  // The toll: three coin, by right, written in the ledger. Running it is breaking the lord's law.
  Relation stopped(group).
  Rule stops when at(party, post) and tolls(keepers, post) and able(keepers) and not tolerates(keepers, party)
    and not stopped(party) and not hostile(chief, party)
    says "The bar stays down. 'The lord's toll,' says the reeve, dipping his pen. 'Three coin. Names?'" {
    Assert stopped(party).
  }
  Action pay_toll(actor: group, site: place) "Pay the lord's toll, three coin" {
    Description "Three coin, written in the ledger. The bar goes up.".
    Requires able(actor) and company(actor) and at(actor, site) and tolls(keepers, site) and at(keepers, site)
      and able(keepers) and not tolerates(keepers, actor) and quantity(actor, gold) >= 3.
    On success { Decrease quantity(actor, gold) by 3. Increase quantity(chief, gold) by 3. Assert tolerates(keepers, actor).
      Assert tolerates(chief, actor). }
    Result "The reeve writes you down, sands the ink, and nods to Fenn, who lifts the bar.".
  }
  // Running the toll, or turning on the lord's men, puts the company outside the law the settlement keeps.
  Rule ran_toll when stopped(party) and not at(party, post) and not tolerates(keepers, party) and tolls(keepers, post) {
    Retract stopped(party). Assert hostile(chief, party). Assert refusesService(provider, party).
  }
  Rule paid_once when tolerates(keepers, party) and not at(party, post) {
    Retract tolerates(keepers, party). Retract tolerates(chief, party). Retract stopped(party).
  }
  Rule outlawed when (routed(chief) or not able(chief) or routed(keepers)) and not refusesService(provider, party)
    says "Word goes down the road ahead of you: the lord's toll-house has been attacked." {
    Assert refusesService(provider, party). Assert hostile(chief, party).
  }
  Rule set_on when at(party, post) and hostile(chief, party) and able(keepers) and not routed(keepers) and tolls(keepers, post)
    says "'Outlaws!' The customs-men draw their swords." {
    Assert assails(keepers, party).
  }
  Observe outlawed_at_inn at market when refusesService(provider, party) "The door of the inn is barred against you, and someone inside says the lord's name loudly.".

  // And the lord answers. Riders go out to the settlement his toll answers to and wait there for whoever did it. They
  // say what they want (the lord's fine, or you) and they mean it: pay, go with them, or fight three armed men. They
  // take prisoners, not lives: beaten, you wake in the lord's lockup all the same, the worse for it (see Mercy).
  Place hall "The lord's hall" is room.
  Person riders "the lord's riders" at hall {
    Role "the lord's riders, sent after whoever turned on his toll". Ancestry human. Calling warrior. Level 2. Numbers 3.
    Called "Aldred", "Wace", "Hubert".
    State waiting "Three riders in the lord's colours wait on the green by their horses, watching the road.".
  }
  Initially Assert serves(riders, chief). Initially Assert takesPrisoners(riders).
  Relation sent(). Relation summoned(group). Relation jailed(group).
  Rule sends when hostile(chief, party) and not sent() says "Behind you, word is going along the road: the lord is sending riders out to {market}, asking after a company that turned on his toll." {
    Assert sent(). Retract at(riders, hall). Assert at(riders, market).
  }
  Rule riders_stop when at(riders, market) and at(party, market) and hostile(chief, party) and not summoned(party)
    and able(riders) says "The riders' captain looks at you, and at a paper in his hand, and back at you. 'In the lord's name,' he says. 'Twenty coin for his toll-house, or you come with us. Fight us and you'll come anyway, and the worse for it.'" {
    Assert summoned(party). Assert halts(riders, party). Set patience(riders) to 3.
  }
  Rule riders_wait when summoned(party) and hostile(chief, party) and together(riders, party) and patience(riders) > 0 {
    Decrease patience(riders) by 1.
  }
  Rule riders_take when summoned(party) and hostile(chief, party) and together(riders, party) and patience(riders) <= 0
    and able(riders) and not captured(riders, party) and not jailed(party)
    says "The captain loses patience. 'Take them.' It is not much of a struggle." { Assert captured(riders, party). }
  Action go_with(actor: group, site: place) "Go with the lord's riders" {
    Description "They take what they can of the fine from your purse, and you spend the night in the lord's lockup. In the morning you are let go, and quits with the lord.".
    Requires able(actor) and company(actor) and at(actor, site) and at(riders, site) and able(riders) and hostile(chief, actor).
    Time 0.
    On success { Assert captured(riders, actor). }
  }
  // Taken, by their leave or not: what they can of the fine, a night in the lockup, and quits in the morning.
  Place lockup "the lord's lockup" is room indoors.
  Passage lockup_door "the lockup door" is door between lockup and market.
  Thing lockup_bar "the lockup door" on lockup_door {
    State barred blocking "A plank door, barred on the outside.".
    State unbarred "The lockup door stands open on the morning.".
  }
  Observe lockup_scene at lockup when true "A stone room with a high slit of a window, and straw on the floor that has seen a good many nights like yours.".
  Rule taken_rich when captured(riders, party) and quantity(party, gold) >= 20 says "They take twenty coin from your purse, write your name in the book, and put you in the lord's lockup for the night." {
    Decrease quantity(party, gold) by 20. Increase quantity(chief, gold) by 20. Retract captured(riders, party). Assert jailed(party).
  }
  Rule taken_poor when captured(riders, party) and quantity(party, gold) < 20 says "They take what coin you have, write your name in the book, and put you in the lord's lockup for the night." {
    Set quantity(party, gold) to 0. Retract captured(riders, party). Assert jailed(party).
  }
  Rule jailed_in when jailed(party) and not at(party, lockup) and state(lockup_bar, barred) {
    Assert at(party, lockup). Retract hostile(chief, party). Assert tolerates(riders, party).
    Retract refusesService(provider, party). Retract summoned(party). Retract at(riders, market). Assert at(riders, hall).
  }
  Rule let_out when jailed(party) and at(party, lockup) and hour(clock) >= 7 and hour(clock) < 12
    and state(lockup_bar, barred) says "In the morning a man in the lord's livery unbars the door. 'Out,' he says. 'You're quits with the lord. Don't make him remember you.'" {
    Assert state(lockup_bar, unbarred). Retract jailed(party).
  }
  Action pay_fine(actor: group, site: place) "Pay the lord's fine, twenty coin" {
    Description "The lord's riders take twenty coin for his toll-house, write you down, and go home; the settlement serves you again.".
    Requires able(actor) and company(actor) and at(actor, site) and at(riders, site) and able(riders) and hostile(chief, actor)
      and quantity(actor, gold) >= 20.
    On success { Decrease quantity(actor, gold) by 20. Increase quantity(chief, gold) by 20. Retract hostile(chief, actor).
      Assert tolerates(riders, actor). Retract refusesService(provider, actor). Retract warned(riders, actor). Retract at(riders, site).
      Assert at(riders, hall). }
    Result "The captain counts it twice, writes in his book, and the riders turn their horses for home. Behind them the door of the inn is unbarred.".
  }

  // Bread, paid for: they take a cartload when they run low, and there is that much less in the inn.
  Rule eats when untilLight(clock) == 1 and quantity(chief, rations) >= 1 and able(keepers) { Decrease quantity(chief, rations) by 1. }
  Rule buys when untilLight(clock) == 2 and quantity(chief, rations) <= 1 and quantity(provider, rations) >= 3 and able(keepers) {
    Decrease quantity(provider, rations) by 3. Increase quantity(chief, rations) by 3. Increase quantity(provider, gold) by 6.
  }

  Rule broken when (not able(chief) or routed(chief)) and tolls(keepers, post) {
    Retract tolls(keepers, post). Retract holds(chief, post).
  }
  Goal not tolls(keepers, post).
}

data/kits/toll-road/deserters/keepers.ky:
Module toll_deserters "Deserters on the road" {
  Description "Deserters from a war nobody here remembers, who have made a stretch of road theirs. They stop whoever comes and take a toll, eat a ration a night, and buy their bread on credit from an inn that cannot refuse them. When the inn has nothing to sell, they come and take it.".
  Entity party: group "Your company".
  Place post "The road they keep" is room.
  Place market "The settlement they buy from" is room.
  Entity provider: group "Who sells them bread on credit".

  Person chief "Sergeant Mawr" at post {
    Role "who keeps the toll". Ancestry human. Calling warrior. Level 2.
    State watching "A big man in a mended red coat sits on a milestone with a pike across his knees, watching the road both ways.".
  }
  Person keepers "the deserters" at post {
    Role "deserters from a war nobody here remembers". Ancestry human. Calling warrior. Level 1. Numbers 3.
    Called "Dobbin", "Hask", "Long Tam".
    Uses go, assail. Plans 6 steps.
    State idle "Three men in the rags of a uniform lean on pikes by a fire at the roadside.".
  }
  Initially Assert serves(keepers, chief). Initially Assert holds(chief, post). Initially Assert posts(keepers, chief).
  Initially Assert tolls(keepers, post). Initially Assert credit(chief, provider).
  Initially Set quantity(chief, rations) to 3.

  // The toll: six coin for the company, paid at the post, good for one passing. Walk on without paying and they
  // remember you.
  Relation stopped(group).
  Rule stops when at(party, post) and tolls(keepers, post) and able(keepers) and not routed(keepers)
    and not tolerates(keepers, party) and not stopped(party) and not hostile(chief, party)
    says "Pikes come down across the road. 'Toll,' says the sergeant, not getting up. 'Six coin, the lot of you. There's a war on.'" {
    Assert stopped(party).
  }
  Action pay_toll(actor: group, site: place) "Pay the deserters' toll, six coin" {
    Description "Six coin, and the pikes go up. Next time, they will want it again.".
    Requires able(actor) and company(actor) and at(actor, site) and tolls(keepers, site) and at(keepers, site)
      and able(keepers) and not tolerates(keepers, actor) and quantity(actor, gold) >= 6.
    On success { Decrease quantity(actor, gold) by 6. Increase quantity(chief, gold) by 6. Assert tolerates(keepers, actor).
      Assert tolerates(chief, actor). }
    Result "The sergeant bites a coin, spits, and waves you through. 'Mind how you go.'".
  }
  Rule ran_toll when stopped(party) and not at(party, post) and not tolerates(keepers, party) and tolls(keepers, post) {
    Retract stopped(party). Assert hostile(chief, party).
  }
  Rule paid_once when tolerates(keepers, party) and not at(party, post) {
    Retract tolerates(keepers, party). Retract tolerates(chief, party). Retract stopped(party).
  }
  Rule set_on when at(party, post) and hostile(chief, party) and able(keepers) and not routed(keepers) and tolls(keepers, post)
    says "'That's them that ran the toll!' The deserters come off the fire with their pikes." {
    Assert assails(keepers, party).
  }

  // Bread on credit: a ration a night, bought two at a time from the inn. An inn with none to sell is robbed.
  Rule eats when untilLight(clock) == 1 and quantity(chief, rations) >= 1 and able(keepers) { Decrease quantity(chief, rations) by 1. }
  Rule buys when untilLight(clock) == 2 and quantity(chief, rations) <= 1 and quantity(provider, rations) >= 2 and able(keepers) {
    Decrease quantity(provider, rations) by 2. Increase quantity(chief, rations) by 2. Increase owes(chief, provider) by 4.
  }
  Rule takes when untilLight(clock) == 2 and quantity(chief, rations) <= 0 and quantity(provider, rations) <= 1 and able(keepers) {
    Increase losses(market) by 2. Increase quantity(chief, rations) by 3.
  }
  Observe robbed at market when losses(market) >= 2 "The deserters came down in the night for bread, and when there was none to sell they took what they found.".
  Topic credit with provider "Ask what the deserters owe" when owes(chief, provider) >= 4 {
    Says "'Owe? They tell me to write it down, so I write it down.' A slate full of marks. 'When the war's over, they say. What war?'".
  }

  // With the sergeant gone the toll goes too: the rest of them drift off up the road.
  Rule broken when (not able(chief) or routed(chief)) and tolls(keepers, post) says "Without the sergeant the deserters stand about a while, then shoulder their pikes and go off up the road." {
    Retract tolls(keepers, post). Assert routed(keepers). Retract holds(chief, post).
  }
  Goal not tolls(keepers, post).
}

