data/rules/ambitions.kyr:
Module world_ambitions "What a power is after, and how it goes about it, a stage at a time" {
  Kind ambition.
  // A power pursues an ambition in stages, the next due so many watches after the last (its pace), while the power
  // is able and the ambition is neither won nor foiled. What each stage does is the ambition's author's: rules on
  // stage(ambition), and on won and foiled.
  Relation pursues(group, ambition). Relation won(ambition). Relation foiled(ambition).
  Measure stage(ambition). Measure stageDue(ambition). Measure pace(ambition).
  Rule ambition_advances when pursues(?g, ?a) and able(?g) and not won(?a) and not foiled(?a)
    and watch(clock) >= stageDue(?a) { Increase stage(?a) by 1. Increase stageDue(?a) by pace(?a). }
  Goal false.
}

data/rules/belief.kyr:
Module world_belief "What people hold true, and how they come to let it go" {
  Kind claim.
  // A claim someone holds, and how firmly they hold it: 3 sure of it, and at nothing they let it go. Whoever will hear
  // reasons (a disputant) can be argued with; what tells against a claim is a fact about the world (refutes), true
  // whether anyone knows it or not.
  Relation believes(group, claim). Measure conviction(group, claim). Relation disputant(group).
  Relation refutes(fact, claim).
  // How a claim was let go: for a reason the world gave (reasoned), or only to good arguing, and whose (swayedBy).
  // Let go for a reason it stays let go. Argued away without one, it is back by morning, and the one who argued it
  // away is scorned for it: not listened to again.
  Relation reasoned(group, claim). Relation swayedBy(group, claim, group). Relation doubts(group, claim).
  Relation scorns(group, group).
  Rule let_go when believes(?g, ?c) and conviction(?g, ?c) < 1 { Retract believes(?g, ?c). Assert doubts(?g, ?c). }
  Rule sway_wears_off when doubts(?g, ?c) and swayedBy(?g, ?c, ?a) and not reasoned(?g, ?c) and untilLight(clock) == 1 {
    Retract doubts(?g, ?c). Retract swayedBy(?g, ?c, ?a). Assert believes(?g, ?c). Set conviction(?g, ?c) to 3.
    Assert scorns(?g, ?a).
  }
  Goal false.
}

data/rules/belongings.kyr:
Module belongings "What the company carries" {
  Kind item. Kind itemkind.
  Relation itemKind(item, itemkind). Relation ownedItem(item, member). Relation wearing(item, member).
  Relation forSale(item). Relation soldBy(item, group) exclusive. Relation wearable(itemkind). Relation consumable(itemkind).
  // What could be used on a member to any end: a remedy for a hurt or an ill they have, or a draught for what it does.
  Relation relieves(member, itemkind).
  // What is used by lighting it, on whoever carries it (a torch, a candle); what burns in something else, and what
  // it burns in (lamp oil, in a lantern).
  Relation lightsUp(itemkind). Relation burns(itemkind, itemkind). Relation fuel(itemkind).
  Relation canTrain(member, ability). Relation teaches(group, ability).
  Relation proficient(member, itemkind).
  Relation wants(group, itemkind). Measure pays(group, itemkind).
  // What a kind of thing is worth (its catalog value), and those who deal in valuables: a merchant who buys any
  // treasure brought in, at its worth, if they have the coin (as Orsino's shops buy junk). Treasure brought home and
  // sold is the company's experience, the first time it is sold: its worth, to each who brought it.
  Measure worth(itemkind). Relation buysValuables(group). Relation realized(item). Relation valuable(itemkind).
  // What a kind of thing weighs, where it says (a module's own kind, "weighing 2"); selm weighs less than nothing.
  Measure mass(itemkind).
  // What each member carries, and can carry (see Burden): a company with anyone carrying more is laden, and goes
  // slowly, at half its pace.
  Measure carried(member). Measure capacity(member).
  Query laden(a: group) means memberOf(?m, a) and carried(?m) > capacity(?m).
  Relation weighed(group).
  Rule laden_felt when laden(?a) and company(?a) and not weighed(?a)
    says "What you carry drags at you: you will go at half your pace until you set something down." { Assert weighed(?a). }
  Rule laden_eased when weighed(?a) and not laden(?a) says "You go easier for what you have set down." { Retract weighed(?a). }
  // How much coin a dealer keeps in the house: what they pay out, trade brings back by the next morning.
  Measure purse(group). Relation appraised(item, group).
  Rule purse_refilled when untilLight(clock) == 1 and buysValuables(?m) and purse(?m) > quantity(?m, gold) {
    Set quantity(?m, gold) to purse(?m).
  }
  // Whose a thing is, and to whom they have lent it. An owner, or one who serves them, who sees the company with it
  // unlent (awake, and there to see it), says so once, in their own words if they have them ("Objects" in a person),
  // and is not the company's friend after. One asleep sees nothing.
  Relation owns(group, item). Relation lends(group, item, group). Relation objected(group, item).
  Relation objection(group, entity).
  Query unlent(o: group, i: item, c: group) means carries(c, i) and not lends(o, i, c) and not objected(o, i).
  Rule owner_objects when owns(?o, ?i) and company(?c) and unlent(?o, ?i, ?c) and perceives(?o, ?c)
    and not objection(?o, ?w) says "{?o} sees {?i} in your hands. 'That is mine.'" {
    Assert objected(?o, ?i). Assert hostile(?o, ?c).
  }
  Rule owner_objects_aloud when owns(?o, ?i) and company(?c) and unlent(?o, ?i, ?c) and perceives(?o, ?c)
    and objection(?o, ?w) says "{?w}" { Assert objected(?o, ?i). Assert hostile(?o, ?c). }
  Rule servant_objects when owns(?o, ?i) and company(?c) and unlent(?o, ?i, ?c) and serves(?s, ?o) and perceives(?s, ?c)
    and not objection(?s, ?w) says "{?s} sees {?i} in your hands, and goes to tell {?o}." {
    Assert objected(?o, ?i). Assert hostile(?o, ?c).
  }
  Rule servant_objects_aloud when owns(?o, ?i) and company(?c) and unlent(?o, ?i, ?c) and serves(?s, ?o)
    and perceives(?s, ?c) and objection(?s, ?w) says "{?w}" { Assert objected(?o, ?i). Assert hostile(?o, ?c). }
  Measure price(item).
  // How many of a kind a seller has out for sale. What is used up (a torch, a flask of oil) comes back to the shelf:
  // each dawn whatever of theirs has been bought and spent is set out again, up to what they began with.
  Measure shelf(group, itemkind).
  Goal false.
  Action take_item(actor: group, find: item, form: itemkind, recipient: member, site: place) "Collect {find} for {recipient}" {
    Time 1 minute.
    Requires able(actor) and at(actor, site) and at(find, site) and not forSale(find) and not benighted(actor)
      and itemKind(find, form) and memberOf(recipient, actor) and awake(recipient) and noticed(find, actor).
    Resolve acquire(find, form, recipient).
    On success { Retract at(find, site). }
    Result "{recipient} takes {find}.".
  }
  Action take_out(actor: group, find: item, form: itemkind, box: thing, recipient: member, site: place) "Take {find} out of {box} for {recipient}" {
    Time 1 minute.
    Requires able(actor) and at(actor, site) and at(box, site) and inside(find, box) and not shut(box)
      and noticed(box, actor) and noticed(find, actor) and not benighted(actor)
      and itemKind(find, form) and memberOf(recipient, actor) and awake(recipient).
    Resolve acquire(find, form, recipient).
    On success { Retract inside(find, box). }
    Result "{recipient} takes {find} from {box}.".
  }
  Action put_in(actor: group, cargo: item, carrier: member, box: thing, site: place) "Put {cargo} in {box}" {
    Time 1 minute.
    Description "Set it in, on or into the thing, where it stays until someone takes it out.".
    Requires able(actor) and at(actor, site) and at(box, site) and receptacle(box) and not shut(box)
      and noticed(box, actor) and not benighted(actor)
      and memberOf(carrier, actor) and awake(carrier) and ownedItem(cargo, carrier).
    Resolve drop(cargo, carrier).
    On success { Assert inside(cargo, box). }
    Result "{carrier} puts {cargo} in {box}.".
  }
  Action buy_item(actor: group, find: item, form: itemkind, recipient: member, merchant: group, site: place) "Buy {find} for {recipient}" {
    Time 3 minutes.
    Requires able(actor) and at(actor, site) and at(find, site) and forSale(find) and itemKind(find, form)
      and memberOf(recipient, actor) and awake(recipient) and soldBy(find, merchant)
      and able(merchant) and not refusesService(merchant, actor) and at(merchant, site) and distinct(actor, merchant) and quantity(actor, gold) >= price(find).
    Resolve purchase(find, form, recipient, actor, merchant).
    On success { Retract at(find, site). Retract forSale(find). Decrease shelf(merchant, form) by 1. }
    Result "{recipient} pays {merchant}, and takes {find}.".
  }
  Action equip_item(actor: group, tool: item, form: itemkind, wearer: member) "Equip {tool} on {wearer}" {
    Time 2 minutes.
    Requires able(actor) and memberOf(wearer, actor) and awake(wearer) and ownedItem(tool, wearer)
      and itemKind(tool, form) and wearable(form) and proficient(wearer, form) and not wearing(tool, wearer).
    Resolve equip(tool, wearer).
    Result "{wearer} readies {tool}.".
  }
  Action use_item(actor: group, dose: item, form: itemkind, carrier: member, recipient: member) "Use {dose} on {recipient}" {
    Time 2 minutes.
    Requires able(actor) and memberOf(carrier, actor) and memberOf(recipient, actor) and awake(carrier)
      and awake(recipient) and ownedItem(dose, carrier) and itemKind(dose, form) and consumable(form) and not lightsUp(form)
      and not fuel(form) and relieves(recipient, form).
    Resolve consume(dose, carrier, recipient).
  }
  Action light_item(actor: group, dose: item, form: itemkind, carrier: member) "Light {dose}" {
    Time 1 minute.
    Requires able(actor) and memberOf(carrier, actor) and awake(carrier) and ownedItem(dose, carrier)
      and itemKind(dose, form) and lightsUp(form).
    Resolve consume(dose, carrier, carrier).
    Result "{carrier} lights {dose}.".
  }
  // A lantern is filled and lit: the flask of oil is spent, and burns in it as long as the flask says.
  Action light_lamp(actor: group, dose: item, form: itemkind, vessel: item, shape: itemkind, carrier: member) "Fill {vessel} from {dose} and light it" {
    Time 2 minutes.
    Requires able(actor) and memberOf(carrier, actor) and awake(carrier) and ownedItem(vessel, carrier)
      and itemKind(vessel, shape) and burns(shape, form) and ownedItem(dose, carrier) and itemKind(dose, form).
    Resolve consume(dose, carrier, carrier).
    Result "{carrier} fills {vessel} and lights it.".
  }
  Action transfer_item(actor: group, cargo: item, carrier: member, recipient: member) "Give {cargo} to {recipient}" {
    Time 1 minute.
    Requires able(actor) and memberOf(carrier, actor) and memberOf(recipient, actor) and awake(carrier)
      and not ownedItem(cargo, recipient) and awake(recipient) and ownedItem(cargo, carrier).
    Resolve transfer_item(cargo, carrier, recipient).
    Result "{carrier} hands {cargo} to {recipient}.".
  }
  // What a companion who has fallen, or cannot stir, was carrying, the others can take.
  Action take_from(actor: group, cargo: item, carrier: member, recipient: member) "Take {cargo} from {carrier} for {recipient}" {
    Time 1 minute.
    Requires able(actor) and memberOf(carrier, actor) and memberOf(recipient, actor) and not awake(carrier)
      and awake(recipient) and ownedItem(cargo, carrier).
    Resolve transfer_item(cargo, carrier, recipient).
    Result "{recipient} takes {cargo} from {carrier}.".
  }
  Action give(actor: group, gift: item, form: itemkind, carrier: member, recipient: group, site: place) "Give {gift} to {recipient}" {
    Time 1 minute.
    Description "Hand it to someone who has asked for it, or will take it. What they do with it is theirs to decide.".
    Requires able(actor) and at(actor, site) and able(recipient) and at(recipient, site) and distinct(actor, recipient)
      and memberOf(carrier, actor) and awake(carrier) and ownedItem(gift, carrier) and itemKind(gift, form)
      and wants(recipient, form).
    Resolve drop(gift, carrier).
    On success { Assert keeps(recipient, gift). }
    Result "{carrier} gives {gift} to {recipient}.".
  }
  // What was taken in front of its owner can be handed back: they will not forget it, but they need not fight for it.
  Action give_back(actor: group, gift: item, carrier: member, owner: group, site: place) "Give {gift} back to {owner}" {
    Time 1 minute.
    Description "Hand back what is theirs. They will remember it was taken; they need not fight you for it.".
    Requires able(actor) and at(actor, site) and able(owner) and at(owner, site) and memberOf(carrier, actor)
      and awake(carrier) and ownedItem(gift, carrier) and owns(owner, gift) and objected(owner, gift).
    Resolve drop(gift, carrier).
    On success { Assert keeps(owner, gift). Retract hostile(owner, actor). }
    Result "{carrier} holds out {gift}, and {owner} takes it back without a word.".
  }
  Action sell(actor: group, ware: item, form: itemkind, carrier: member, buyer: group, site: place) "Sell {ware} to {buyer}" {
    Time 3 minutes.
    Description "Someone who buys this kind of thing pays what they said they would, if they have the coin.".
    Requires able(actor) and at(actor, site) and able(buyer) and at(buyer, site) and distinct(actor, buyer)
      and memberOf(carrier, actor) and awake(carrier) and ownedItem(ware, carrier) and itemKind(ware, form)
      and pays(buyer, form) >= 1 and quantity(buyer, gold) >= pays(buyer, form) and not refusesService(buyer, actor).
    Resolve realize(ware, carrier, actor).
    On success { Assert keeps(buyer, ware). Assert realized(ware). Decrease quantity(buyer, gold) by pays(buyer, form).
      Increase quantity(actor, gold) by pays(buyer, form). }
    Result "{buyer} takes {ware}, and counts out the coin for it.".
  }
  Action sell_valuable(actor: group, ware: item, form: itemkind, carrier: member, buyer: group, site: place) "Sell {ware} to {buyer}" {
    Time 3 minutes.
    Description "Someone who deals in valuables pays what a thing is worth, if they have the coin. The first time a treasure is sold, what it is worth is experience for each of the company.".
    Requires able(actor) and at(actor, site) and able(buyer) and at(buyer, site) and distinct(actor, buyer)
      and memberOf(carrier, actor) and awake(carrier) and ownedItem(ware, carrier) and itemKind(ware, form)
      and buysValuables(buyer) and valuable(form) and worth(form) >= 1 and pays(buyer, form) < 1
      and quantity(buyer, gold) >= worth(form) and not refusesService(buyer, actor).
    Resolve realize(ware, carrier, actor).
    On success { Assert keeps(buyer, ware). Assert realized(ware). Decrease quantity(buyer, gold) by worth(form).
      Increase quantity(actor, gold) by worth(form). }
    Result "{buyer} turns {ware} over in the light, names a price, and counts out the coin.".
  }
  // A dealer without the coin for a treasure still says what it is worth, and whether to wait or go elsewhere.
  Action appraise(actor: group, ware: item, form: itemkind, carrier: member, buyer: group, site: place) "Show {ware} to {buyer}" {
    Time 2 minutes.
    Description "Someone who deals in valuables says what a thing is worth, when they have not the coin for it.".
    Requires able(actor) and at(actor, site) and able(buyer) and at(buyer, site) and distinct(actor, buyer)
      and memberOf(carrier, actor) and awake(carrier) and ownedItem(ware, carrier) and itemKind(ware, form)
      and buysValuables(buyer) and valuable(form) and worth(form) >= 1 and pays(buyer, form) < 1
      and quantity(buyer, gold) < worth(form) and purse(buyer) >= worth(form) and not appraised(ware, buyer)
      and not refusesService(buyer, actor).
    On success { Assert appraised(ware, buyer). }
    Result "{buyer} turns {ware} over in the light, and hands it back. 'Worth {worth(form)} coin, that. I have not got it in the house today; come back in the morning.'".
  }
  Action appraise_beyond(actor: group, ware: item, form: itemkind, carrier: member, buyer: group, site: place) "Show {ware} to {buyer}" {
    Time 2 minutes.
    Description "Someone who deals in valuables says what a thing is worth, when it is worth more than they ever have.".
    Requires able(actor) and at(actor, site) and able(buyer) and at(buyer, site) and distinct(actor, buyer)
      and memberOf(carrier, actor) and awake(carrier) and ownedItem(ware, carrier) and itemKind(ware, form)
      and buysValuables(buyer) and valuable(form) and worth(form) >= 1 and pays(buyer, form) < 1
      and purse(buyer) < worth(form) and not appraised(ware, buyer) and not refusesService(buyer, actor).
    On success { Assert appraised(ware, buyer). }
    Result "{buyer} turns {ware} over in the light for a long time, and hands it back. 'Worth {worth(form)} coin, that, and there is not that much in this place. Take it to a town.'".
  }
  Action put_item(actor: group, cargo: item, carrier: member, site: place) "Set down {cargo}" {
    Time 1 minute.
    Requires able(actor) and at(actor, site) and memberOf(carrier, actor) and awake(carrier) and ownedItem(cargo, carrier).
    Resolve drop(cargo, carrier).
    On success { Assert at(cargo, site). }
    Result "{carrier} sets {cargo} down.".
  }
  Action train_member(actor: group, mentor: group, student: member, lesson: ability, site: place) "Train {student} in {lesson}" {
    Requires able(actor) and able(mentor) and distinct(actor, mentor) and at(actor, site) and at(mentor, site)
      and memberOf(student, actor) and awake(student) and teaches(mentor, lesson) and canTrain(student, lesson).
    Resolve train(lesson, student).
    Time 6.
    Result "{mentor} spends an hour drilling {student} in {lesson}.".
  }
}

data/rules/care.kyr:
Module care "Rest, mending and lessons" {
  Kind member. Kind ability. Kind reward. Kind circle.
  Entity circle_1: circle "first-level slot". Entity circle_2: circle "second-level slot".
  Entity circle_3: circle "third-level slot". Entity circle_4: circle "fourth-level slot".
  Entity circle_5: circle "fifth-level slot". Entity circle_6: circle "sixth-level slot".
  Entity circle_7: circle "seventh-level slot". Entity circle_8: circle "eighth-level slot".
  Entity circle_9: circle "ninth-level slot".
  Relation swappable(member, circle, ability, ability).
  Kind quality.
  Entity strength: quality "Strength". Entity dexterity: quality "Dexterity". Entity constitution: quality "Constitution".
  Entity intelligence: quality "Intelligence". Entity wisdom: quality "Wisdom". Entity charisma: quality "Charisma".
  Relation improvable(member). Relation learnable(member, ability).
  Kind feat. Relation featOpen(member, feat).
  Relation memberOf(member, group).
  Relation fieldUsable(ability).
  // One who falls lies senseless (fallen) until a rest, when they come round or die where they fell (slain).
  Relation awake(member). Relation fallen(member). Relation slain(member). Relation needsCare(member). Relation canCast(member, ability). Relation treatable(member, ability).
  Relation restful(place). Relation offeredAt(reward, place). Relation giftEffect(reward, ability).
  Relation rewardFor(reward, fact). Relation claimed(reward).
  Goal false.
  Action field_spell(actor: group, caster: member, technique: ability, recipient: member, site: place) "Have {caster} use {technique} on {recipient}" {
    Time 2 minutes.
    Description "A healing, a cleansing or a ward, used between fights, for its usual cost in mana.".
    Requires able(actor) and at(actor, site) and memberOf(caster, actor) and memberOf(recipient, actor)
      and fieldUsable(technique) and awake(caster) and awake(recipient) and canCast(caster, technique) and treatable(recipient, technique).
    Resolve invoke(technique, caster, recipient).
    Result "{caster} uses {technique} on {recipient}.".
  }
  Action prepare_spell(actor: group, caster: member, tier: circle, outgoing: ability, incoming: ability) "Have {caster} prepare {incoming} in place of {outgoing}, in a {tier}" {
    Description "An hour of study or prayer. A spell prepared in a slot still ready can be cast at once; in a slot already spent, after the next rest.".
    Requires able(actor) and memberOf(caster, actor) and awake(caster) and swappable(caster, tier, outgoing, incoming).
    Time 6.
    Resolve prepare(caster, tier, outgoing, incoming).
    Result "{caster} spends an hour over {incoming}.".
  }
  Action raise_quality(actor: group, member: member, quality: quality) "Have {member} raise {quality}" {
    Description "Each level gained lets a companion raise one quality by a point. Strength lands blows and Dexterity turns them; Constitution adds hit points at the next level; Intelligence, Wisdom or Charisma feeds a caster's spells.".
    Requires able(actor) and memberOf(member, actor) and awake(member) and improvable(member).
    Resolve improve(member, quality).
    Result "{member} grows in {quality}.".
  }
  Action learn_spell(actor: group, member: member, spell: ability) "Have {member} learn {spell}" {
    Description "Each level gained lets a caster add a spell of their tradition, of a level they can cast, to what they know. It can be prepared from then on.".
    Requires able(actor) and memberOf(member, actor) and awake(member) and learnable(member, spell).
    Resolve learn(member, spell).
    Result "{member} learns {spell}.".
  }
  Action take_feat(actor: group, member: member, choice: feat) "Have {member} take up {choice}" {
    Description "At the fifth, tenth and fifteenth levels a companion takes up one of their calling's feats. Some rule others out: a knight is no barbarian.".
    Requires able(actor) and memberOf(member, actor) and awake(member) and featOpen(member, choice).
    Resolve feat(member, choice).
    Result "{member} takes up {choice}.".
  }
  // The dead the company cannot have raised it lays to rest, and goes on without them.
  Action bury_companion(actor: group, lost: member, site: place) "Lay {lost} to rest" {
    Description "A grave dug and words said over it: an hour. They leave the company, and what they carried goes with them.".
    Requires able(actor) and at(actor, site) and memberOf(lost, actor) and slain(lost) and not indoors(site).
    Time 6. Resolve inter(lost).
    Result "You dig a grave for {lost} and lay them in it, and say what can be said over them. Then you go on without them.".
  }
  Action rest(actor: group, site: place) "Rest and recover at {site}" {
    Description "Six hours and a ration, somewhere safe. The living get their strength and mana back, and bleeding is stopped; poison is not mended. Whoever has fallen comes round, or dies where they fell (a d20 and their Constitution against 10). The world does not wait while you sleep.".
    Requires able(actor) and at(actor, site) and restful(site) and quantity(actor, rations) >= 1.
    Time 36. Resolve recover(actor). Interrupted when threatened(actor).
    // Its ration is the company's meal, eaten as meals are (world_needs): one the day's meal has already eaten in the
    // six hours is not eaten twice.
    On success { Set nextMeal(actor) to watch(clock). Set lastSlept(actor) to watch(clock). Retract weary(actor). }
    Result "You eat, bind your hurts and sleep for six hours.".
  }
  // A company with nothing to eat is still offered its rest, and told why it cannot have it.
  Action rest_unfed(actor: group, site: place) "Rest and recover at {site}" {
    Description "Six hours and a ration, somewhere safe; and there is no ration left.".
    Requires able(actor) and at(actor, site) and restful(site) and quantity(actor, rations) < 1.
    Time 1 minute.
    Result "There is nothing left to eat. You could lie down, but you would get up no better: a rest wants a ration with it, and there are rations at any inn.".
  }
  Action learn_reward(actor: group, gift: reward, recipient: member, lesson: ability, proof: fact, site: place) "Accept {gift} for {recipient}" {
    Time 1 minute.
    Requires able(actor) and at(actor, site) and offeredAt(gift, site) and memberOf(recipient, actor)
      and awake(recipient) and giftEffect(gift, lesson) and rewardFor(gift, proof) and knows(actor, proof)
      and not claimed(gift).
    Resolve reward(lesson, recipient).
    On success { Assert claimed(gift). Retract offeredAt(gift, site). Retract at(gift, site). }
    Result "{recipient} studies {gift} until {lesson} comes easily.".
  }
}

data/rules/core.kyr:
Module world_core "Bodies, places, time and the shared catalog" {
  Kind group. Kind place. Kind good. Kind clock. Kind capability.
  Entity gold: good "coin". Entity rations: good "ration". Entity clock: clock "Time".
  Entity woodcraft: capability "Woodcraft". Entity mending: capability "Mending".
  Entity lockwork: capability "Lockwork". Entity trapwork: capability "Trapwork".
  Entity wayfinding: capability "Wayfinding". Entity digging: capability "Digging".
  Entity brawn: capability "Brawn". Entity stealth: capability "Stealth".
  Entity lore: capability "Lore". Entity rites: capability "Rites of the dead".
  Entity climbing: capability "Climbing". Entity light: capability "Light". Entity flame: capability "Flame".
  Entity sunlight: capability "Sunlight". Entity perception: capability "Keen eyes".
  Entity persuasion: capability "Persuasion". Entity deception: capability "Deception".
  Entity intimidation: capability "Intimidation". Entity insight: capability "Insight".
  // How hard a check is (Resolve check(actor, persuasion, dc_fair)): ten, thirteen, sixteen or nineteen to beat.
  Kind difficulty. Entity dc_easy: difficulty "easy". Entity dc_fair: difficulty "fair".
  Entity dc_hard: difficulty "hard". Entity dc_formidable: difficulty "formidable".
  // The lie of the land a region is: what a party's perks of place (an elven tribe in a forest) answer to.
  Kind terrainkind. Relation terrain(place, terrainkind).
  Entity forest: terrainkind "forest". Entity marsh: terrainkind "marsh". Entity mountain: terrainkind "mountain".
  Entity frost: terrainkind "frost". Entity desert: terrainkind "desert". Entity hills: terrainkind "hills".
  // The land a stretch of country is (a river's vale, a wood, a mere, a pass): what a chart draws it as. The names
  // are prefixed, as every module shares them and an author's own place may well be called "pass".
  Kind landkind. Relation landform(place, landkind).
  Entity land_river: landkind "river". Entity land_lake: landkind "lake". Entity land_peak: landkind "peak".
  Entity land_pass: landkind "pass". Entity land_wood: landkind "wood".
  Relation at(entity, place) exclusive.
  // How big a settlement is: what can be seen of it from the road, and what it can spare.
  Kind sizekind. Relation townSize(place, sizekind).
  Entity size_hamlet: sizekind "hamlet". Entity size_village: sizekind "village". Entity size_town: sizekind "town".
  Relation able(group). Relation dead(group). Relation distinct(group, group).
  Relation closed(place). Relation indoors(place). Relation settled(place).
  Relation peaceable(group). Relation routed(group).
  Relation dark().
  Relation witnessedAttack(group, group, group).
  Relation refusesService(group, group).
  Relation capable(group, capability). Relation brings(member, capability).
  Relation serves(group, group).
  Query allied(a: group, b: group) means serves(a, b) or serves(b, a) or (serves(a, ?m) and serves(b, ?m)).
  Relation unlit(place). Relation company(group).
  // Where a company has been: once it has stood somewhere, it knows the place and can find it again.
  Relation been(group, place).
  Rule been_there when company(?c) and at(?c, ?p) and not been(?c, ?p) { Assert been(?c, ?p). }
  // A place's law: everyone in it, or anywhere within it, fights under that condition (a plane where fire burns
  // small, a temple where no blade is drawn). The law names a catalog condition.
  Kind law. Relation law(place, law).
  // A place where light dies: only sunlight shows anything there.
  Relation lightless(place).
  // One who lets another be: does not bar its way or fall on it (a toll paid, a bribe taken, recruits believed).
  Relation tolerates(group, group).
  // Someone falling on another: on the company, it starts a fight there and then.
  Relation assails(group, group).
  // Someone stopping another where they stand (a challenge, a hold-up): on the company, whatever it was doing is
  // broken off, and it must deal with them.
  Relation halts(group, group).
  // A company on the way, between where it set out and where it is going: enRoute(company, by this passage).
  Relation enRoute(group, passage).
  Query benighted(a: group) means company(a) and at(a, ?p) and not capable(a, sunlight)
    and ((unlit(?p) and not capable(a, light)) or lightless(?p)).
  // The kind of work the company has done (its backgrounds' families): what those who do the same work know it by.
  Kind craft. Relation craft(group, craft).
  Entity craft_wild: craft "the wild". Entity craft_roads: craft "the roads". Entity craft_mechanisms: craft "mechanisms".
  Entity craft_shadows: craft "the shadows". Entity craft_healing: craft "healing". Entity craft_faith: craft "faith".
  Entity craft_learning: craft "learning". Entity craft_earth: craft "the earth". Entity craft_arms: craft "arms".
  Entity craft_water: craft "the water". Entity craft_stage: craft "the stage". Entity craft_trade: craft "trade".
  Entity craft_court: craft "the court". Entity craft_margins: craft "the margins".
  // How someone carries themselves, which shows in what they say (Orsino's personalities); and the words they are
  // spoken of in. Someone with no manner given has one all the same (see VoiceContext).
  Kind manner. Relation manner(group, manner).
  Entity manner_proud: manner "proud". Entity manner_grim: manner "grim". Entity manner_cheerful: manner "cheerful".
  Entity manner_acerbic: manner "acerbic". Entity manner_compassionate: manner "compassionate".
  Entity manner_stoic: manner "stoic". Entity manner_jovial: manner "jovial".
  Kind pronoun. Relation pronouns(group, pronoun).
  Entity pron_he: pronoun "he". Entity pron_she: pronoun "she". Entity pron_they: pronoun "they". Entity pron_it: pronoun "it".
  // Who is awake to the world. A group that the day's round or a spell has put to sleep sees nothing that happens.
  Relation asleep(group).
  Query alert(g: group) means able(g) and not asleep(g).
  // Whether one would see what another does where both are: awake, there, and not hidden from them.
  Relation unseen(group, group).
  Query perceives(o: group, s: group) means at(o, ?p) and at(s, ?p) and alert(o) and not unseen(s, o).
  Measure quantity(entity, good). Measure watch(clock). Measure encounterXp(group).
  Goal false.
  // Someone who means the company no good where it is: a long wait or a rest is broken off when one arrives.
  Query threatened(a: group) means at(a, ?p) and at(?o, ?p) and able(?o) and distinct(?o, a) and not peaceable(?o)
    and not allied(?o, a) and not tolerates(?o, a).
  Action wait(actor: group) "Wait a while" {
    Requires able(actor). Time 1.
  }
  // A company that cannot move (all of it asleep, or held fast) can only lie as it is until it can.
  Action lie_still(actor: group) "Lie as you are" {
    Description "You cannot move. Time passes over you until you can.".
    Requires company(actor) and not able(actor) and not dead(actor). Time 1.
  }
  Action wait_hour(actor: group) "Wait an hour" {
    Requires able(actor). Time 6. Interrupted when threatened(actor).
    Result "An hour passes.".
  }
  Measure untilLight(clock). Measure untilMorning(clock).
  // The hour of the day (0 to 23) and the day since the company came (1, 2…): what people's days are kept by.
  Measure hour(clock). Measure day(clock).
  // A die thrown each watch, 1 to 100, for what is left to chance: dice(clock) for the world, and dice(x) for each
  // thing's own, so that what is left to chance in two places, or for two people, does not fall out alike.
  Measure dice(entity).
  // The season by the campaign's calendar, when it keeps one: 1 spring, 2 summer, 3 autumn, 4 winter (0: none).
  Measure season(clock).
  Action wait_for_light(actor: group) "Wait until first light" {
    Requires able(actor) and dark(). Time untilLight(clock). Interrupted when threatened(actor).
    Result "The sky greys, then lightens. It is morning.".
  }
  Measure untilDark(clock). Measure untilTurn(clock).
  Action wait_for_dark(actor: group) "Wait until dark" {
    Requires able(actor) and not dark(). Time untilDark(clock). Interrupted when threatened(actor).
    Result "The light goes. It is dark.".
  }
  Action wait_watch(actor: group) "Wait and watch" {
    Description "Until someone comes or goes, or something changes here; or until the day turns.".
    Requires able(actor). Time untilTurn(clock). Interrupted when threatened(actor). Watchful.
    Result "Nothing comes, and nothing changes. The hours go by.".
  }
  Action assail(actor: group, prey: group, site: place) "Fall on {prey}" {
    Description "Someone who means harm closes and attacks.".
    Requires able(actor) and at(actor, site) and at(prey, site) and able(prey) and distinct(actor, prey)
      and not peaceable(actor) and not allied(actor, prey) and not tolerates(actor, prey) and not company(actor).
    On success { Assert assails(actor, prey). }
  }
  Action attack(actor: group, opponent: group, site: place) "Attack {opponent}" {
    Description "Once it starts it goes on until one side is down or runs, and whoever falls may not get up.".
    Requires able(actor) and able(opponent) and distinct(actor, opponent) and at(actor, site) and reaches(actor, opponent)
      and not peaceable(opponent).
    Resolve combat(opponent).
  }
}

data/rules/devotion.kyr:
Module world_devotion "Shrines, offerings and the favour of the gods" {
  // A shrine is a thing kept for a god (an altar, a statue, a spring led into a basin), and a god is of a faith: a
  // domain of Orsino's pantheon, whose blessing the god gives to those who keep the shrine's observance. The faith
  // names are prefixed, as every module shares them and an author may well call a place "light".
  Kind shrine. Kind faith.
  Relation shrineOf(shrine, faith). Measure offering(shrine). Relation honored(group, shrine).
  Entity faith_life: faith "life". Entity faith_light: faith "light". Entity faith_nature: faith "nature".
  Entity faith_war: faith "war". Entity faith_knowledge: faith "knowledge". Entity faith_death: faith "death".
  Entity faith_storms: faith "storms". Entity faith_order: faith "order". Entity faith_oceans: faith "the sea".
  Entity faith_love: faith "love". Entity faith_magic: faith "magic". Entity faith_trickery: faith "trickery".
  Entity faith_darkness: faith "darkness". Entity faith_chaos: faith "chaos". Entity faith_poison: faith "poison".
  Goal false.
  Action make_offering(actor: group, altar: shrine, devotion: faith, recipient: member, site: place) "Leave an offering, and ask the god's favour for {recipient}" {
    Description "Coin left at a shrine and its observance kept, as Orsino's shrines ask. A good god's favour heals a little and another's hurts a little; either goes with the one it was asked for into their next ten turns of fighting, with the blessing of the god's faith. Once a day at each shrine.".
    Requires able(actor) and at(actor, site) and at(altar, site) and shrineOf(altar, devotion)
      and memberOf(recipient, actor) and awake(recipient) and quantity(actor, gold) >= offering(altar)
      and not honored(actor, altar).
    Time 3.
    Resolve bless(altar, devotion, recipient).
    On success { Decrease quantity(actor, gold) by offering(altar). Assert honored(actor, altar). }
    Result "You leave {offering(altar)} coin at {altar} and keep the observance.".
  }
  // An observance can be kept again the next day.
  Rule devotion_renewed when untilLight(clock) == 1 and honored(?g, ?a) { Retract honored(?g, ?a). }
}

data/rules/discovery.kyr:
Module discovery_rules "Reliable discovery and trusted reports" {
  Kind fact. Kind source.
  Relation established(fact).
  Relation reveals(source, fact).
  Relation intact(source).
  Relation noticeable(source).
  Relation destructible(source).
  Relation mayExamine(group, source).
  Relation knows(group, fact).
  Relation assumesFalse(group, fact).
  Relation trusts(group, group).
  Relation learnedFrom(group, source, fact).
  Relation toldBy(group, group, fact).
  Relation publicPlace(place).
  Relation testimony(group, source).
  Relation witnessed(group, fact).
  Relation searched(group, place).
  // A place where a story is being told (a cart gone off the road, a man under it), and the story: nothing else that
  // could be taken for part of it happens there by chance (a carrier's wheel in the ditch).
  Relation staged(place, fact).
  // What was so and is no longer (a child's fever, once it has broken or the child has died): still known to whoever
  // knew it, but no longer passed on as news.
  Relation stale(fact).
  Goal false.
  Action examine(actor: group, witness: source, statement: fact, site: place) "Examine {witness}" {
    Time 5 minutes.
    Requires able(actor) and at(actor, site) and at(witness, site) and not benighted(actor)
      and noticeable(witness) and intact(witness) and mayExamine(actor, witness)
      and reveals(witness, statement) and established(statement) and not learnedFrom(actor, witness, statement).
    On success {
      Assert knows(actor, statement). Retract assumesFalse(actor, statement).
      Assert learnedFrom(actor, witness, statement).
    }
  }
  Action tell(actor: group, recipient: group, statement: fact, site: place) "Tell {recipient}: {statement}" {
    Time 3 minutes.
    Result "{recipient} hears you out, and believes you.".
    Requires able(actor) and able(recipient) and distinct(actor, recipient)
      and at(actor, site) and at(recipient, site) and trusts(recipient, actor)
      and knows(actor, statement) and established(statement) and not stale(statement)
      and not toldBy(recipient, actor, statement).
    On success {
      Assert knows(recipient, statement). Retract assumesFalse(recipient, statement).
      Assert toldBy(recipient, actor, statement).
    }
  }
  Action ask(actor: group, informant: group, topic: source, statement: fact, site: place) "Ask {informant} about {topic}" {
    Time 5 minutes.
    Result "{informant} tells you what they have heard about {topic}.".
    Description "They tell you what they know of it.".
    Requires able(actor) and able(informant) and distinct(actor, informant)
      and at(actor, site) and at(informant, site) and testimony(informant, topic)
      and reveals(topic, statement) and noticeable(topic)
      and knows(informant, statement) and established(statement) and not stale(statement)
      and not knows(actor, statement).
    On success {
      Assert knows(actor, statement). Retract assumesFalse(actor, statement).
      Assert toldBy(actor, informant, statement).
    }
  }
  Action search(actor: group, site: place) "Search {site}" {
    Description "Go over the place: walls, floor, furniture, the backs of things. Twenty minutes, once; a search the light gives out on is not made.".
    Requires able(actor) and at(actor, site) and not benighted(actor) and not searched(actor, site).
    Time 2. Resolve rummage(actor). Interrupted when threatened(actor) or benighted(actor).
    On success { Assert searched(actor, site). }
    Result "You search {site} with care, a little at a time.".
  }
  Action destroy_source(actor: group, witness: source, site: place) "Destroy {witness}" {
    Result "You destroy {witness}.".
    Requires able(actor) and at(actor, site) and at(witness, site)
      and noticeable(witness) and intact(witness) and destructible(witness).
    On success { Retract intact(witness). }
  }
}

data/rules/dominion.kyr:
Module dominion "Who holds what, how a power stands toward a company, and how its agents go about the land" {
  Kind byway.
  Relation holds(group, place). Relation keeps(group, entity). Relation covets(group, entity).
  // Those who take prisoners rather than kill (the lord's riders, a reeve's men), and whom they have taken: what
  // happens to a company beaten by them is theirs to say (see Mercy).
  Relation takesPrisoners(group). Relation captured(group, group).
  Relation bywayFrom(byway, place). Relation bywayTo(byway, place). Measure bywayTime(byway).
  Relation knowsWay(group, byway). Relation travelling(group, byway).
  Query keepsKind(g: group, k: itemkind) means keeps(g, ?i) and itemKind(?i, k).
  // How a power stands toward a company, kept by the power and obeyed by everyone who serves it: alarmed when
  // something has gone wrong in what it holds; admitting a company to come and go; or hostile to it on sight.
  Relation alarmed(group). Relation admits(group, group). Relation hostile(group, group).
  Rule admitted when admits(?power, ?company) and serves(?member, ?power) and not tolerates(?member, ?company)
    and not hostile(?power, ?company) { Assert tolerates(?member, ?company). }
  Rule turned when hostile(?power, ?company) and serves(?member, ?power) and tolerates(?member, ?company) {
    Retract tolerates(?member, ?company).
  }
  Rule unadmitted when hostile(?power, ?company) and admits(?power, ?company) { Retract admits(?power, ?company). }
  // Who takes a toll where: a collector standing on a road. A road nobody tolls is open; trade on it moves.
  Relation tolls(group, place).
  // Where a power buys on credit, and what it owes there.
  Relation credit(group, group). Measure owes(group, group).
  // What raiders, tithe-takers and foragers have taken from a place.
  Measure losses(place).
  // A stronghold its holder has left. A power that covets it sends the band it posts, by night, and holds it.
  Relation vacant(place). Relation posts(group, group).
  Rule seized when vacant(?site) and covets(?power, ?site) and posts(?band, ?power) and able(?power) and able(?band)
    and untilLight(clock) == 1 {
    Retract vacant(?site). Assert holds(?power, ?site). Assert at(?band, ?site).
  }
  Goal false.
  Action depart(actor: group, way: byway, origin: place, destination: place) "Set out by {way} toward {destination}" {
    Description "Someone who knows the land's old ways leaves for a distant place, and is out of sight until they arrive.".
    Requires able(actor) and knowsWay(actor, way) and at(actor, origin) and bywayFrom(way, origin)
      and bywayTo(way, destination).
    On success { Retract at(actor, origin). Assert travelling(actor, way). }
  }
  Action arrive(actor: group, way: byway, destination: place) "Come by {way} to {destination}" {
    Requires travelling(actor, way) and bywayTo(way, destination).
    Time bywayTime(way).
    On success { Retract travelling(actor, way). Assert at(actor, destination). }
  }
}

data/rules/growing.kyr:
Module world_growing "What grows where, and what can be gathered from it" {
  // A stand of something that grows (willows over the water, yarrow at the wayside), and what can be gathered from it
  // there a little at a time: each crop an item of the kind it yields, until the stand is stripped.
  Relation grows(scenery). Relation crop(item, scenery).
  Goal false.
  Action gather(actor: group, find: item, form: itemkind, stand: scenery, recipient: member, site: place) "Gather {find} for {recipient}" {
    Description "Cut it, strip it or pick it, and carry it away: what grows wild is anyone's who takes the trouble.".
    Requires able(actor) and company(actor) and at(actor, site) and at(stand, site) and grows(stand)
      and crop(find, stand) and itemKind(find, form) and memberOf(recipient, actor) and awake(recipient)
      and not benighted(actor).
    Time 1.
    Resolve acquire(find, form, recipient).
    On success { Retract crop(find, stand). Retract inside(find, stand). }
    Result "{recipient} gathers {find}.".
  }
}

data/rules/inhabitants.kyr:
Module inhabitants "How creatures that live somewhere answer those who come into it" {
  // A creature's temperament says how it meets a company that comes where it lives. A territorial one warns, then
  // falls on whoever stays; a defensive one warns, and fights only for its lair; a proud one names a price; a savage
  // one falls on you at once; one that lies in ambush strikes unless keen eyes spot it first; an obedient one keeps
  // its post and nothing else; a wary one slinks away, and fights only when cornered in its refuge. A group of one
  // species takes its species' temperament; a place may give any group one (temper_savage, temper_proud…).
  Kind temperament.
  Entity temper_territorial: temperament "territorial". Entity temper_defensive: temperament "defensive".
  Entity temper_wary: temperament "wary". Entity temper_ambush: temperament "ambush".
  Entity temper_proud: temperament "proud".
  Entity temper_obedient: temperament "obedient". Entity temper_savage: temperament "savage".
  // A tame creature (a dog, a horse, a cat about a house) knows people: it comes to see who you are, and lets you
  // make much of it.
  Entity temper_tame: temperament "tame".
  Relation temperament(group, temperament).
  // Where it lives and what it defends; where it goes when beaten or frightened off.
  Relation lair(group, place). Relation refuge(group, place).
  // What it does, in the place's own words: its warning, its onslaught, what makes it flinch, how it yields.
  Relation warning(group, entity). Relation onslaught(group, entity). Relation flinch(group, entity).
  Relation plea(group, entity). Relation greeting(group, entity).
  Relation greeted(group, group). Relation petted(group, group).
  // What drives it off (sunlight, flame), and the price a proud one names.
  Relation fears(group, capability). Measure tribute(group).
  Relation warned(group, group). Relation yielded(group, group).
  // Plain words for a creature whose place gives it none, by temperament: temper_words_<temperament>_<what>.
  Entity temper_words_territorial_warning: fact "{?g} stands its ground and watches you. It will not have you here for long.".
  Entity temper_words_territorial_onslaught: fact "{?g} comes at you.".
  Entity temper_words_defensive_warning: fact "{?g} will not let you come any nearer.".
  Entity temper_words_defensive_onslaught: fact "{?g} comes at you to drive you off.".
  Entity temper_words_savage_onslaught: fact "{?g} comes at you without a sound.".
  Entity temper_words_ambush_warning: fact "Something is waiting here, and you see it before it moves: {?g}.".
  Entity temper_words_ambush_onslaught: fact "{?g} springs out at you.".
  Entity temper_words_obedient_onslaught: fact "{?g} comes at you, as it was made to.".
  Entity temper_words_wary_flinch: fact "{?g} slips away from you.".
  Entity temper_words_wary_onslaught: fact "Cornered, {?g} turns on you.".
  Entity temper_words_proud_warning: fact "{?g} looks at you as if you owed it something.".
  // The same words for a band of more than one, where they differ.
  Entity temper_words_territorial_warning_many: fact "{?g} stand their ground and watch you. They will not have you here for long.".
  Entity temper_words_territorial_onslaught_many: fact "{?g} come at you.".
  Entity temper_words_defensive_onslaught_many: fact "{?g} come at you to drive you off.".
  Entity temper_words_savage_onslaught_many: fact "{?g} come at you without a sound.".
  Entity temper_words_ambush_warning_many: fact "Something is waiting here, and you see them before they move: {?g}.".
  Entity temper_words_ambush_onslaught_many: fact "{?g} spring out at you.".
  Entity temper_words_obedient_onslaught_many: fact "{?g} come at you, as they were made to.".
  Entity temper_words_wary_flinch_many: fact "{?g} slip away from you.".
  Entity temper_words_wary_onslaught_many: fact "Cornered, {?g} turn on you.".
  Entity temper_words_proud_warning_many: fact "{?g} look at you as if you owed them something.".
  // The watch it waits until, once it has warned, before it comes at whoever stays: the rest of this one, however
  // many small things are done in it.
  Measure patience(group).
  Query confronts(g: group, c: group) means together(g, c) and company(c) and able(g) and not routed(g)
    and not tolerates(g, c) and not assails(g, c).

  // Fear comes first: whatever it fears, brought into its presence, drives it back to its refuge.
  Rule temper_shies when fears(?g, ?k) and company(?c) and together(?g, ?c) and capable(?c, ?k) and able(?g)
    and refuge(?g, ?r) and not at(?g, ?r) and flinch(?g, ?f) says "{?f}" {
    Assert at(?g, ?r). Retract assails(?g, ?c). Retract warned(?g, ?c).
  }
  // Beaten, it may beg; then it goes back to its refuge, and comes out again the next day.
  Rule temper_yields when routed(?g) and company(?c) and together(?g, ?c) and able(?g) and plea(?g, ?p)
    and not yielded(?g, ?c) says "{?p}" {
    Assert yielded(?g, ?c). Assert tolerates(?g, ?c). Retract assails(?g, ?c).
  }
  Rule temper_falls_back when routed(?g) and refuge(?g, ?r) and not at(?g, ?r) { Assert at(?g, ?r). }
  Rule temper_rallies when routed(?g) and refuge(?g, ?r) and at(?g, ?r) and untilLight(clock) == 1 {
    Retract routed(?g).
  }
  // A warning spent: whoever stayed is fallen on (for a defensive one, only in its lair).
  Rule temper_closes when warned(?g, ?c) and together(?g, ?c) and able(?g) and not routed(?g) and not tolerates(?g, ?c)
    and patience(?g) <= watch(clock) and not temperament(?g, temper_defensive) and onslaught(?g, ?o) says "{?o}" {
    Assert assails(?g, ?c). Retract warned(?g, ?c).
  }
  Rule temper_defends when warned(?g, ?c) and temperament(?g, temper_defensive) and lair(?g, ?l) and at(?c, ?l)
    and at(?g, ?l) and able(?g) and not routed(?g)
    and not tolerates(?g, ?c) and patience(?g) <= watch(clock) and onslaught(?g, ?o) says "{?o}" {
    Assert assails(?g, ?c). Retract warned(?g, ?c).
  }
  Rule temper_let_go when warned(?g, ?c) and not together(?g, ?c) { Retract warned(?g, ?c). }
  // The first meeting: a warning stops the company where it stands, whatever it was doing, and it must answer.
  Rule temper_warns when temperament(?g, ?t) and warnsFirst(?t) and company(?c) and confronts(?g, ?c) and not warned(?g, ?c)
    and warning(?g, ?w) says "{?w}" {
    Assert warned(?g, ?c). Assert halts(?g, ?c). Set patience(?g) to watch(clock) + 1.
  }
  Relation warnsFirst(temperament).
  Initially Assert warnsFirst(temper_territorial). Initially Assert warnsFirst(temper_defensive).
  Initially Assert warnsFirst(temper_proud).
  Rule temper_falls_on when temperament(?g, temper_savage) and company(?c) and confronts(?g, ?c) and onslaught(?g, ?o)
    says "{?o}" {
    Assert assails(?g, ?c).
  }
  Rule temper_springs when temperament(?g, temper_ambush) and company(?c) and confronts(?g, ?c)
    and not capable(?c, perception) and not warned(?g, ?c)
    and onslaught(?g, ?o) says "{?o}" {
    Assert assails(?g, ?c).
  }
  Rule temper_spotted when temperament(?g, temper_ambush) and company(?c) and confronts(?g, ?c)
    and capable(?c, perception) and not warned(?g, ?c)
    and warning(?g, ?w) says "{?w}" {
    Assert warned(?g, ?c). Assert halts(?g, ?c). Set patience(?g) to watch(clock) + 1.
  }
  Rule temper_keeps_post when temperament(?g, temper_obedient) and company(?c) and confronts(?g, ?c)
    and lair(?g, ?p) and at(?g, ?p)
    and onslaught(?g, ?o) says "{?o}" {
    Assert assails(?g, ?c).
  }
  Rule temper_cornered when temperament(?g, temper_wary) and company(?c) and confronts(?g, ?c)
    and refuge(?g, ?r) and at(?g, ?r)
    and onslaught(?g, ?o) says "{?o}" {
    Assert assails(?g, ?c).
  }
  Rule temper_slinks when temperament(?g, temper_wary) and company(?c) and confronts(?g, ?c)
    and refuge(?g, ?r) and not at(?g, ?r)
    and flinch(?g, ?f) says "{?f}" {
    Assert at(?g, ?r).
  }
  // A tame one greets whoever comes, once, if it is awake: in its own words (Greets), or as its kind does
  // (data/voice/greet.json).
  Rule temper_greets when temperament(?g, temper_tame) and company(?c) and together(?g, ?c) and alert(?g)
    and not greeted(?g, ?c) and not hostile(?g, ?c) {
    Assert greeted(?g, ?c). Assert tolerates(?g, ?c).
  }
  Goal false.
  // A tame creature lets itself be made much of, by anyone it has not taken against.
  Action pet(actor: group, animal: group, site: place) "Make much of {animal}" {
    Description "Crouch down, hold out a hand, scratch behind its ears.".
    Requires able(actor) and company(actor) and at(actor, site) and at(animal, site) and temperament(animal, temper_tame)
      and able(animal) and not hostile(animal, actor).
    Time 0.
    On success { Assert petted(animal, actor). Assert tolerates(animal, actor). Assert greeted(animal, actor). }
  }
  // Words instead of blows, for a band that can be spoken to and will hear words (one that warns, or watches from
  // the edge of the light): talked round, it lets the company be; faced down, it gives way. The one of the company best
  // at it speaks, once; it is rolled only when it could go either way. Talked to badly, a band gives you the rest of
  // the watch to be gone, and then comes at you; warned off badly, it comes at you at once.
  Relation hears(temperament). Relation spokenTo(group, group).
  Initially Assert hears(temper_territorial). Initially Assert hears(temper_defensive).
  Initially Assert hears(temper_wary). Initially Assert hears(temper_proud).
  Action talk_round(actor: group, hearers: group, site: place) "Ask {hearers} to let you by" {
    Time 3 minutes.
    Requires able(actor) and company(actor) and at(actor, site) and at(hearers, site) and able(hearers) and talks(hearers)
      and temperament(hearers, ?t) and hears(?t) and not tolerates(hearers, actor) and not assails(hearers, actor)
      and not routed(hearers) and not spokenTo(hearers, actor).
    Resolve check(actor, persuasion, dc_fair).
    On success { Assert spokenTo(hearers, actor). Assert tolerates(hearers, actor). Retract warned(hearers, actor). }
    On failure { Assert spokenTo(hearers, actor). Assert warned(hearers, actor). Set patience(hearers) to watch(clock) + 2. }
    Result "You talk it over with {hearers}, and in the end you are let be.".
    Otherwise "You talk it over with {hearers}, and get nowhere: there will be no more patience for you here.".
  }
  Action face_down(actor: group, hearers: group, site: place) "Warn {hearers} off" {
    Time 2 minutes.
    Requires able(actor) and company(actor) and at(actor, site) and at(hearers, site) and able(hearers) and talks(hearers)
      and temperament(hearers, ?t) and hears(?t) and not tolerates(hearers, actor) and not assails(hearers, actor)
      and not routed(hearers) and not spokenTo(hearers, actor).
    Resolve check(actor, intimidation, dc_hard).
    On success { Assert spokenTo(hearers, actor). Assert tolerates(hearers, actor). Retract warned(hearers, actor). }
    On failure { Assert spokenTo(hearers, actor). Assert assails(hearers, actor). }
    Result "You face {hearers} out, and you are given room.".
    Otherwise "You face {hearers} out, and it goes the wrong way.".
  }
  // A proud creature's price, paid: it lets the company be.
  Action pay_tribute(actor: group, lord: group, site: place) "Give {lord} what it asks" {
    Time 2 minutes.
    Description "A proud creature names a price for letting you pass; paid, it keeps its word.".
    Requires able(actor) and company(actor) and at(actor, site) and at(lord, site) and warned(lord, actor)
      and temperament(lord, temper_proud) and quantity(actor, gold) >= tribute(lord).
    On success {
      Decrease quantity(actor, gold) by tribute(lord). Increase quantity(lord, gold) by tribute(lord).
      Assert tolerates(lord, actor). Retract warned(lord, actor).
    }
    Result "{lord} takes it, and lets you be.".
  }
}

data/rules/needs.kyr:
Module world_needs "Food and sleep" {
  Relation eats(group). Relation hungry(group).
  Measure nextMeal(group).
  // A company that sleeps grows weary eighteen hours after it last woke from sleep (a bed, a camp, a rest), and stays
  // so until it sleeps again; a weary company fights the worse for it (see Campaign.encounterBattle). A sleep that can
  // be broken (a camp, a rest) has its effects when it ends; a bed at an inn cannot, and has them when it begins, so
  // it sets lastSlept to when the night will end.
  Relation sleeps(group). Relation weary(group).
  Measure lastSlept(group).
  Goal false.
  Rule meal when eats(?g) and watch(clock) >= nextMeal(?g) and quantity(?g, rations) >= 1 {
    Decrease quantity(?g, rations) by 1. Increase nextMeal(?g) by 144. Retract hungry(?g).
  }
  Rule hunger when eats(?g) and watch(clock) >= nextMeal(?g) and quantity(?g, rations) < 1 and not hungry(?g) {
    Assert hungry(?g).
  }
  // Told by the narrator when it comes (see Narrator.exchange), not said: it does not stop a wait for light.
  Rule weariness when sleeps(?g) and watch(clock) >= lastSlept(?g) + 108 and not weary(?g) {
    Assert weary(?g).
  }
}

data/rules/people.kyr:
Module world_people "Company and intention" {
  Relation acceptsEscort(group, group). Relation dismissed(group, group).
  // Someone taken from home: who set them free, where home is, and what their people will give whoever brings them
  // back. Brought home by a company they are home, and grateful to it, and the thanks are paid.
  Relation freedBy(group, group). Relation home(group, place). Relation cameHome(group). Relation grateful(group, group).
  Measure thanks(group).
  Rule brought_home when following(?person, ?company) and home(?person, ?place) and at(?person, ?place)
    and not cameHome(?person) {
    Retract following(?person, ?company). Assert cameHome(?person). Assert grateful(?person, ?company).
    Increase quantity(?company, gold) by thanks(?person).
  }
  // Who someone is to the one who plays: family (kin), or someone expecting them with a letter or an errand (expects);
  // what they owe someone is dominion's owes. An origin says so at the outset; what people say and do follows it.
  Relation kin(group, group). Relation expects(group, group).
  // The settlement the one who plays grew up in, where its people know them (neighbours, not strangers); and someone
  // they owe money, until it is paid.
  Relation homeOf(group, place). Relation inDebtTo(group, group).
  // What someone is to the one who plays, in the words the page names them by ("your brother"), where the origin says.
  Relation kinship(group, entity).
  // Someone who would join the company, once they are willing, for their hire (which may be nothing); and whoever has
  // joined it, who goes where it goes and can be talked to on the way.
  Relation willing(group, group). Measure hire(group). Relation travelsWith(group, group).
  // Who someone who has joined now is among the company's members: they answer on the way only while that member is
  // awake (not fallen, not asleep, not laid to rest).
  Relation joinedAs(member, group).
  // A traveller of the country who has joined (a fellow, as against the one who plays): how much of their own story
  // they have told, and whether they have told some tonight. A story is told a part a night.
  Relation fellow(member). Measure confided(group). Relation hushed(group).
  // What someone says on joining the company, or leaving it, in their own words (Joins, Leaves): said instead of the
  // voice tables' (data/voice/join.json, part.json), which speak by what they are to the one who plays.
  Relation joining(group, entity). Relation parting(group, entity).
  // The painting shown beside someone in conversation (Likeness "fisherman"): one of the corpus, for what they do.
  Relation likeness(group, entity).
  Rule hush_lifts when hushed(?c) and not dark() { Retract hushed(?c). }
  Goal false.
  Action recruit(actor: group, recruit: group, site: place) "Ask {recruit} to join the company" {
    Time 5 minutes.
    Description "They come with you from now on: they fight beside you, and what they can do, you can.".
    Requires able(actor) and company(actor) and able(recruit) and distinct(actor, recruit) and at(actor, site)
      and at(recruit, site) and willing(recruit, actor) and quantity(actor, gold) >= hire(recruit).
    Resolve enlist(recruit, actor).
    On success { Decrease quantity(actor, gold) by hire(recruit). Retract willing(recruit, actor). Retract at(recruit, site).
      Assert travelsWith(recruit, actor). }
  }
  Action lead(actor: group, companion: group, site: place) "Ask {companion} to come with you" {
    Time 1 minute.
    Requires able(actor) and able(companion) and distinct(actor, companion) and at(actor, site)
      and at(companion, site) and acceptsEscort(companion, actor) and not following(companion, actor).
    On success { Assert following(companion, actor). Retract dismissed(companion, actor). }
  }
  Action part_ways(actor: group, companion: group, site: place) "Let {companion} make their own way" {
    Time 1 minute.
    Requires able(actor) and able(companion) and at(actor, site) and at(companion, site)
      and acceptsEscort(companion, actor) and following(companion, actor) and not hobbled(companion).
    On success { Retract following(companion, actor). Assert dismissed(companion, actor). }
  }
  // Someone who would come with you, if you led them, can be told not to wait: they go their own way.
  Action send_off(actor: group, companion: group, site: place) "Tell {companion} not to wait for you" {
    Time 1 minute.
    Requires able(actor) and able(companion) and at(actor, site) and at(companion, site)
      and acceptsEscort(companion, actor) and not following(companion, actor) and not dismissed(companion, actor)
      and not hobbled(companion).
    On success { Assert dismissed(companion, actor). }
  }

  // Talking to someone: the company's attention on one person, until it takes its leave or goes. Anyone who is a
  // person (not an animal or a beast) talks, and anyone with something to be asked (Topic) does. Speaking to them
  // takes no time; they answer it (a greeting, from the voice tables), and what can be put to them is put in it.
  Relation talks(group). Relation addressed(group, group).
  Action talk_to(actor: group, person: group, site: place) "Talk to {person}" {
    Description "Go over and speak to them.".
    Requires able(actor) and company(actor) and at(actor, site) and at(person, site) and talks(person) and able(person)
      and not asleep(person) and not hostile(person, actor) and not addressed(person, actor) and distinct(actor, person).
    Time 0.
    On success { Assert addressed(person, actor). }
  }
  Action take_leave(actor: group, person: group, site: place) "Take your leave of {person}" {
    Requires able(actor) and at(actor, site) and addressed(person, actor).
    Time 0.
    On success { Retract addressed(person, actor). }
  }
  Rule conversation_ends when addressed(?p, ?c) and not together(?p, ?c) { Retract addressed(?p, ?c). }
}

data/rules/probing.kyr:
Module probing "Trying things: looking closely, prodding, prying, burning, pushing, listening" {
  Entity looking: verb "looked over closely". Entity prodding: verb "prodded with a pole".
  Entity prying: verb "pried at with a bar". Entity burning: verb "put to the flame".
  Entity pushing: verb "pushed and pulled". Entity listening: verb "listened at".
  // Anything that can be handled can be tried, in the ways its look suits (and any its author adds); what it does
  // when tried is the author's (an observation, an event, a rule on tried). A try that finds nothing says so;
  // offering it never reveals anything.
  Initially Assert needs(prodding, pole). Initially Assert needs(prying, crowbar). Initially Assert needs(burning, flame).
  Goal false.
  Action look_closely(actor: group, target: entity, site: place) "Look closely at {target}" {
    Time 2 minutes.
    Requires able(actor) and at(actor, site) and probeable(target) and reaches(actor, target) and not benighted(actor)
      and suits(target, looking) and not tried(target, looking).
    On success { Assert tried(target, looking). }
    Result "You look closely at {target}.".
  }
  Action prod(actor: group, target: entity, site: place) "Prod {target} with the pole" {
    Time 2 minutes.
    Requires able(actor) and at(actor, site) and probeable(target) and reaches(actor, target) and not benighted(actor)
      and equippedFor(actor, prodding) and suits(target, prodding) and not tried(target, prodding)
      and not harmless(target).
    On success { Assert tried(target, prodding). }
    Result "You prod {target} with the pole, from as far off as it allows.".
  }
  Action pry(actor: group, target: entity, site: place) "Pry at {target} with the bar" {
    Time 3 minutes.
    Requires able(actor) and at(actor, site) and probeable(target) and reaches(actor, target) and not benighted(actor)
      and equippedFor(actor, prying) and suits(target, prying) and not tried(target, prying).
    On success { Assert tried(target, prying). }
    Result "You get the bar into {target} and lean on it.".
  }
  Action burn(actor: group, target: entity, site: place) "Hold a flame to {target}" {
    Time 2 minutes.
    Requires able(actor) and at(actor, site) and probeable(target) and reaches(actor, target)
      and equippedFor(actor, burning) and suits(target, burning) and not tried(target, burning).
    On success { Assert tried(target, burning). }
    Result "You hold a flame to {target}.".
  }
  Action push(actor: group, target: entity, site: place) "Push and pull at {target}" {
    Time 2 minutes.
    Requires able(actor) and at(actor, site) and probeable(target) and reaches(actor, target) and not benighted(actor)
      and suits(target, pushing) and not tried(target, pushing).
    On success { Assert tried(target, pushing). }
    Result "You push at {target}, then pull.".
  }
  Action listen(actor: group, target: entity, site: place) "Listen at {target}" {
    Time 2 minutes.
    Requires able(actor) and at(actor, site) and probeable(target) and reaches(actor, target) and not benighted(actor)
      and suits(target, listening) and not tried(target, listening).
    On success { Assert tried(target, listening). }
    Result "You put an ear to {target}, and hold your breath.".
  }
}

data/rules/services.kyr:
Module world_services "Lodging, goods and camping" {
  Kind service. Kind servicekind.
  Entity lodging: servicekind "Lodging". Entity healing: servicekind "Healing". Entity passage_fare: servicekind "Passage".
  Entity raising: servicekind "Raising the dead".
  Relation offers(group, service). Relation serviceOf(service, servicekind). Relation sells(group, good).
  Measure fee(service). Measure goodsPrice(group, good).
  Goal false.
  Action take_lodging(actor: group, host: group, service: service, site: place) "Take {service} from {host}" {
    Requires able(actor) and able(host) and distinct(actor, host) and at(actor, site) and at(host, site)
      and not refusesService(host, actor) and offers(host, service) and serviceOf(service, lodging) and quantity(actor, gold) >= fee(service).
    Time untilMorning(clock). Resolve recover(actor).
    On success { Decrease quantity(actor, gold) by fee(service). Increase quantity(host, gold) by fee(service).
      Retract hungry(actor). Increase nextMeal(actor) by 144.
      Set lastSlept(actor) to watch(clock) + untilMorning(clock). Retract weary(actor). }
    Result "You eat what is put in front of you, and sleep long, under a roof.".
  }
  Action take_healing(actor: group, healer: group, service: service, site: place) "Ask {healer} for {service}" {
    Requires able(actor) and able(healer) and distinct(actor, healer) and at(actor, site) and at(healer, site)
      and not refusesService(healer, actor) and offers(healer, service) and serviceOf(service, healing) and quantity(actor, gold) >= fee(service).
    Time 6. Resolve recover(actor).
    On success { Decrease quantity(actor, gold) by fee(service). Increase quantity(healer, gold) by fee(service). }
    Result "{healer} cleans and dresses every wound in the company.".
  }
  // A priest who can call the dead back (Orsino's Raise Dead) does it at the shrine, for a great price, through a
  // night's vigil: the companion comes back weak, with half their health, and what killed them gone.
  Action take_raising(actor: group, healer: group, service: service, lost: member, site: place) "Ask {healer} to raise {lost} from the dead" {
    Description "A long vigil at the shrine, a night's worth of hours, and the price of it. They come back with half their health.".
    Requires able(actor) and able(healer) and distinct(actor, healer) and at(actor, site) and at(healer, site)
      and not refusesService(healer, actor) and offers(healer, service) and serviceOf(service, raising)
      and memberOf(lost, actor) and fallen(lost) and quantity(actor, gold) >= fee(service).
    Time untilMorning(clock). Resolve raise(lost).
    On success { Decrease quantity(actor, gold) by fee(service). Increase quantity(healer, gold) by fee(service). }
    Result "{healer} keeps the vigil over {lost} through the long hours, and at the end of them {lost} draws a breath, and then another.".
  }
  Action buy_goods(actor: group, seller: group, goods: good, site: place) "Buy one {goods} from {seller}" {
    Time 3 minutes.
    Requires able(actor) and able(seller) and distinct(actor, seller) and at(actor, site) and at(seller, site)
      and not refusesService(seller, actor) and sells(seller, goods) and quantity(seller, goods) >= 1 and quantity(actor, gold) >= goodsPrice(seller, goods).
    On success { Decrease quantity(actor, gold) by goodsPrice(seller, goods). Increase quantity(seller, gold) by goodsPrice(seller, goods).
      Decrease quantity(seller, goods) by 1. Increase quantity(actor, goods) by 1. }
    Result "{seller} counts the coins and hands over a {goods}.".
  }
  Action camp(actor: group, site: place) "Make camp at {site}" {
    Requires able(actor) and at(actor, site) and not indoors(site) and not settled(site) and not hungry(actor).
    Time untilMorning(clock). Resolve rough(actor). Interrupted when threatened(actor).
    On success { Set lastSlept(actor) to watch(clock). Retract weary(actor). }
    Result "You find what shelter there is, and sleep as well as you can, with one ear open.".
  }
}

