data/voice/address.json:
{
  "about": "Someone is spoken to: how they take it, by whether they have spoken with the company before (moment first or again), who the company is to them (bond), their manner, and the hour. Said once, when the company turns its attention to them; what can be put to them follows. Someone with a temper of their own (wary, territorial, defensive, as a place's dwellers are) takes it in that temper, whoever they are to the company.",
  "kinds": [
    "address"
  ],
  "lines": [
    {
      "id": "address.first.1",
      "when": {
        "moment": "first"
      },
      "text": "{Actor} looks up, and takes a moment to place you, and fails. ‘Yes?’"
    },
    {
      "id": "address.first.2",
      "when": {
        "moment": "first"
      },
      "text": "{Actor} straightens, and wipes {their} hands, and waits to hear what you want."
    },
    {
      "id": "address.first.3",
      "when": {
        "moment": "first"
      },
      "text": "‘You’re not from here,’ says {actor}. It is not a question, and not quite unfriendly."
    },
    {
      "id": "address.first.4",
      "when": {
        "moment": "first"
      },
      "text": "{Actor} gives you the look people keep for strangers who have stopped walking. ‘Can I help you?’"
    },
    {
      "id": "address.again.1",
      "when": {
        "moment": "again"
      },
      "text": "‘You again,’ says {actor}, and it seems to be all right."
    },
    {
      "id": "address.again.2",
      "when": {
        "moment": "again"
      },
      "text": "{Actor} nods to you as to someone {they} [have|has] spoken to before."
    },
    {
      "id": "address.again.3",
      "when": {
        "moment": "again"
      },
      "text": "{Actor} sees you coming and leaves off what {they} [were|was] doing."
    },
    {
      "id": "address.first.night",
      "when": {
        "moment": "first",
        "time": "night"
      },
      "text": "{Actor} peers at you in the bad light. ‘It’s late to be making acquaintances.’"
    },
    {
      "id": "address.first.morning",
      "when": {
        "moment": "first",
        "time": "morning"
      },
      "text": "‘Morning,’ says {actor}, the way people say it before they have decided about you."
    },
    {
      "id": "address.again.night",
      "when": {
        "moment": "again",
        "time": "night"
      },
      "text": "‘Still about?’ says {actor}. ‘You’ll want your bed, like the rest of us.’"
    },
    {
      "id": "address.first.cheerful",
      "when": {
        "moment": "first",
        "manner": "cheerful"
      },
      "text": "‘Well now,’ says {actor}, brightening at the sight of a new face. ‘What brings you?’"
    },
    {
      "id": "address.first.cheerful.2",
      "when": {
        "moment": "first",
        "manner": "cheerful"
      },
      "text": "{Actor} grins before you have said anything at all. ‘You look like a person with a question.’"
    },
    {
      "id": "address.again.cheerful",
      "when": {
        "moment": "again",
        "manner": "cheerful"
      },
      "text": "‘There you are!’ says {actor}, as if {they} had been expecting you."
    },
    {
      "id": "address.first.grim",
      "when": {
        "moment": "first",
        "manner": "grim"
      },
      "text": "{Actor} looks at you for longer than is comfortable. ‘Well?’"
    },
    {
      "id": "address.first.grim.2",
      "when": {
        "moment": "first",
        "manner": "grim"
      },
      "text": "{Actor} does not stop working. ‘Say it, then.’"
    },
    {
      "id": "address.again.grim",
      "when": {
        "moment": "again",
        "manner": "grim"
      },
      "text": "‘You,’ says {actor}, neither pleased nor otherwise."
    },
    {
      "id": "address.first.stoic",
      "when": {
        "moment": "first",
        "manner": "stoic"
      },
      "text": "{Actor} looks up, and puts {their} hands still, and waits for you to say what you want."
    },
    {
      "id": "address.again.stoic",
      "when": {
        "moment": "again",
        "manner": "stoic"
      },
      "text": "{Actor} inclines {their} head, which seems to be a whole greeting."
    },
    {
      "id": "address.first.jovial",
      "when": {
        "moment": "first",
        "manner": "jovial"
      },
      "text": "‘A traveller!’ says {actor}, loud enough for half the place to hear. ‘Sit, sit. Or stand. What’ll it be?’"
    },
    {
      "id": "address.again.jovial",
      "when": {
        "moment": "again",
        "manner": "jovial"
      },
      "text": "‘Back for more of my wisdom,’ says {actor}. ‘Can’t say I blame you.’"
    },
    {
      "id": "address.first.compassionate",
      "when": {
        "moment": "first",
        "manner": "compassionate"
      },
      "text": "{Actor} takes in the state of you: the road dust, the tiredness. ‘You’ve come a way. What do you need?’"
    },
    {
      "id": "address.again.compassionate",
      "when": {
        "moment": "again",
        "manner": "compassionate"
      },
      "text": "‘How are you getting on?’ asks {actor}, and seems to want to know."
    },
    {
      "id": "address.first.proud",
      "when": {
        "moment": "first",
        "manner": "proud"
      },
      "text": "{Actor} lets you speak first, as is plainly {their} due."
    },
    {
      "id": "address.first.proud.2",
      "when": {
        "moment": "first",
        "manner": "proud"
      },
      "text": "‘I don’t know you,’ says {actor}, and waits to be told why {they} should."
    },
    {
      "id": "address.again.proud",
      "when": {
        "moment": "again",
        "manner": "proud"
      },
      "text": "{Actor} acknowledges you with the smallest movement of the chin."
    },
    {
      "id": "address.first.acerbic",
      "when": {
        "moment": "first",
        "manner": "acerbic"
      },
      "text": "‘Lost?’ says {actor}. ‘People usually are, when they come over to me.’"
    },
    {
      "id": "address.first.acerbic.2",
      "when": {
        "moment": "first",
        "manner": "acerbic"
      },
      "text": "{Actor} looks you up and down. ‘Whatever it is, the answer’s probably no. Go on.’"
    },
    {
      "id": "address.again.acerbic",
      "when": {
        "moment": "again",
        "manner": "acerbic"
      },
      "text": "‘Oh, it’s you,’ says {actor}. ‘I wondered when you’d be back to bother me.’"
    },
    {
      "id": "address.kin.first",
      "when": {
        "bond": "kin",
        "moment": "first"
      },
      "text": "{Actor} looks at you as if counting the years you have been away, and then just holds on to you a moment."
    },
    {
      "id": "address.kin.again",
      "when": {
        "bond": "kin",
        "moment": "again"
      },
      "text": "‘What is it?’ says {actor}, as family say it: not unkindly, and not getting up."
    },
    {
      "id": "address.kin.again.2",
      "when": {
        "bond": "kin",
        "moment": "again"
      },
      "text": "{Actor} makes room for you without being asked."
    },
    {
      "id": "address.expected.first",
      "when": {
        "bond": "expected",
        "moment": "first"
      },
      "text": "{Actor} takes in the road on your boots, and that you have come straight to {them}, and waits to hear what you have brought."
    },
    {
      "id": "address.expected.first.2",
      "when": {
        "bond": "expected",
        "moment": "first"
      },
      "text": "‘You’ve come a long way to find somebody,’ says {actor}. ‘Is it me?’"
    },
    {
      "id": "address.creditor.first",
      "when": {
        "bond": "creditor",
        "moment": "first"
      },
      "text": "{Actor} looks at your hands before your face, to see whether there is anything in them."
    },
    {
      "id": "address.creditor.again",
      "when": {
        "bond": "creditor",
        "moment": "again"
      },
      "text": "‘Well?’ says {actor}, and looks at your purse rather than at you."
    },
    {
      "id": "address.friend.first",
      "when": {
        "bond": "friend",
        "moment": "first"
      },
      "text": "{Actor} knows you before you are close, and comes to meet you. ‘I wondered if you’d come this way.’"
    },
    {
      "id": "address.friend.again",
      "when": {
        "bond": "friend",
        "moment": "again"
      },
      "text": "‘Sit down a minute,’ says {actor}. ‘You make me tired, standing.’"
    },
    {
      "id": "address.neighbour.first",
      "when": {
        "bond": "neighbour",
        "moment": "first"
      },
      "text": "{Actor} looks twice, and then a third time. ‘Well. Look who it is.’"
    },
    {
      "id": "address.neighbour.first.2",
      "when": {
        "bond": "neighbour",
        "moment": "first"
      },
      "text": "‘You’re back, then,’ says {actor}, as if you had been gone a week and not three years."
    },
    {
      "id": "address.neighbour.again",
      "when": {
        "bond": "neighbour",
        "moment": "again"
      },
      "text": "{Actor} nods to you the way the place nods to its own."
    },
    {
      "id": "address.fellow.again",
      "when": {
        "bond": "fellow",
        "moment": "again"
      },
      "text": "{Actor} falls into step beside you. ‘What is it?’"
    },
    {
      "id": "address.fellow.again.2",
      "when": {
        "bond": "fellow",
        "moment": "again"
      },
      "text": "‘Thinking something?’ says {actor}. ‘You’ve got that look.’"
    },
    {
      "id": "address.wary.first.1",
      "when": {
        "moment": "first",
        "temper": "wary",
        "kind": "person"
      },
      "text": "{Actor} [draw|draws] back to the edge of your light and [watch|watches] you, weapons low but ready. Nobody speaks first."
    },
    {
      "id": "address.wary.first.2",
      "when": {
        "moment": "first",
        "temper": "wary",
        "kind": "person"
      },
      "text": "{Actor} [go|goes] still when your light finds {them}. There is a mutter, and an answer, and then {they} [wait|waits] to see what you will do."
    },
    {
      "id": "address.wary.again.1",
      "when": {
        "moment": "again",
        "temper": "wary",
        "kind": "person"
      },
      "text": "{Actor} [know|knows] you now, and [keep|keeps] the same distance as before."
    },
    {
      "id": "address.territorial.first.1",
      "when": {
        "moment": "first",
        "temper": "territorial",
        "kind": "person"
      },
      "text": "{Actor} [close|closes] up across the way with weapons out. ‘No further,’ comes a voice. ‘This is ours.’"
    },
    {
      "id": "address.territorial.again.1",
      "when": {
        "moment": "again",
        "temper": "territorial",
        "kind": "person"
      },
      "text": "‘You again,’ says one of {actor}. ‘Say it quick, and then go back the way you came.’"
    },
    {
      "id": "address.defensive.first.1",
      "when": {
        "moment": "first",
        "temper": "defensive",
        "kind": "person"
      },
      "text": "{Actor} [back|backs] against the wall at the sight of you, blades up. ‘We want no trouble,’ one of {them} says, ‘and we will give it if we have to.’"
    },
    {
      "id": "address.defensive.again.1",
      "when": {
        "moment": "again",
        "temper": "defensive",
        "kind": "person"
      },
      "text": "{Actor} [let|lets] you come no nearer than before."
    },
    {
      "id": "address.proud.first.d1",
      "when": {
        "moment": "first",
        "temper": "proud",
        "kind": "person"
      },
      "text": "{Actor} [look|looks] you over as if you had come to pay {them} something. ‘Well?’"
    }
  ]
}

data/voice/combat.json:
{
  "about": "What fighters say or do at the turning points of a fight (kinds: engage, crit, kill, miss, dodge, hurt, fall, flee, summon, summoned, revived): by the fighter's manner (side: company) or kind of foe (role). Most are Orsino's barks (source orsino); the narrator says one now and then, never two in one exchange, and never the same one twice in a fight.",
  "kinds": [
    "engage",
    "crit",
    "kill",
    "miss",
    "dodge",
    "hurt",
    "fall",
    "flee",
    "summon",
    "summoned",
    "revived"
  ],
  "lines": [
    {
      "id": "kill.kyr.compassionate.1",
      "when": {
        "manner": "compassionate",
        "side": "company"
      },
      "text": "{Actor} stands over the body a moment, breathing hard, and does not look pleased."
    },
    {
      "id": "miss.kyr.compassionate.1",
      "when": {
        "manner": "compassionate",
        "side": "company"
      },
      "text": "{Actor} swears under {their} breath and sets {their} feet again."
    },
    {
      "id": "miss.kyr.stoic.1",
      "when": {
        "manner": "stoic",
        "side": "company"
      },
      "text": "{Actor} recovers without a word."
    },
    {
      "id": "hurt.kyr.grim.1",
      "when": {
        "manner": "grim",
        "side": "company"
      },
      "text": "{Actor} takes it, and grunts, and keeps coming."
    },
    {
      "id": "hurt.kyr.cheerful.1",
      "when": {
        "manner": [
          "cheerful",
          "jovial"
        ],
        "side": "company"
      },
      "text": "'That,' says {actor} through {their} teeth, 'is going to hurt in the morning.'"
    },
    {
      "id": "flee.kyr.beast.1",
      "when": {
        "kind": "animal"
      },
      "text": "{Actor} [break|breaks] and [run|runs], and [is|is] gone into the undergrowth."
    },
    {
      "id": "engage.kyr.beast.1",
      "when": {
        "kind": "animal"
      },
      "text": "{Actor} [come|comes] at you low and fast."
    },
    {
      "id": "summoned.orsino.generic.onSummonReceived.0",
      "text": "From the trembling earth, {actor} rises to join the fray!",
      "source": {
        "orsino": "barks:generic.onSummonReceived"
      }
    },
    {
      "id": "summoned.orsino.generic.onSummonReceived.1",
      "text": "{Actor} emerges from the shadows, ready to fight!",
      "source": {
        "orsino": "barks:generic.onSummonReceived"
      }
    },
    {
      "id": "summoned.orsino.generic.onSummonReceived.2",
      "text": "'I heed your call!', declares {actor} as they enter the battle.",
      "source": {
        "orsino": "barks:generic.onSummonReceived"
      }
    },
    {
      "id": "revived.orsino.generic.onResurrect.0",
      "text": "{Actor} gasps and returns to the fight!",
      "source": {
        "orsino": "barks:generic.onResurrect"
      }
    },
    {
      "id": "revived.orsino.generic.onResurrect.1",
      "text": "{Actor} shakes off death and stands once more!",
      "source": {
        "orsino": "barks:generic.onResurrect"
      }
    },
    {
      "id": "fall.orsino.generic.onFall.0",
      "text": "{Actor} falls to the ground, defeated.",
      "source": {
        "orsino": "barks:generic.onFall"
      }
    },
    {
      "id": "fall.orsino.generic.onFall.1",
      "text": "{Actor} collapses, unable to continue.",
      "source": {
        "orsino": "barks:generic.onFall"
      }
    },
    {
      "id": "flee.orsino.generic.onFlee.0",
      "text": "{Actor} turns and runs away!",
      "source": {
        "orsino": "barks:generic.onFlee"
      }
    },
    {
      "id": "flee.orsino.generic.onFlee.1",
      "text": "{Actor} flees the battle!",
      "source": {
        "orsino": "barks:generic.onFlee"
      }
    },
    {
      "id": "kill.orsino.personality.proud.onKill.0",
      "when": {
        "manner": "proud",
        "side": "company"
      },
      "text": "{Actor} stands over the fallen foe: ‘As expected.’",
      "source": {
        "orsino": "barks:personality.proud.onKill"
      }
    },
    {
      "id": "crit.orsino.personality.proud.onCrit.0",
      "when": {
        "manner": "proud",
        "side": "company"
      },
      "text": "{Actor} smirks: ‘Flawless.’",
      "source": {
        "orsino": "barks:personality.proud.onCrit"
      }
    },
    {
      "id": "miss.orsino.personality.proud.onMiss.0",
      "when": {
        "manner": "proud",
        "side": "company"
      },
      "text": "{Actor} scowls in irritation.",
      "source": {
        "orsino": "barks:personality.proud.onMiss"
      }
    },
    {
      "id": "kill.orsino.personality.grim.onKill.0",
      "when": {
        "manner": "grim",
        "side": "company"
      },
      "text": "{Actor} says coldly: ‘Another one falls.’",
      "source": {
        "orsino": "barks:personality.grim.onKill"
      }
    },
    {
      "id": "crit.orsino.personality.grim.onCrit.0",
      "when": {
        "manner": "grim",
        "side": "company"
      },
      "text": "{Actor} strikes without emotion.",
      "source": {
        "orsino": "barks:personality.grim.onCrit"
      }
    },
    {
      "id": "miss.orsino.personality.grim.onMiss.0",
      "when": {
        "manner": "grim",
        "side": "company"
      },
      "text": "{Actor} growls: ‘Damn it.’",
      "source": {
        "orsino": "barks:personality.grim.onMiss"
      }
    },
    {
      "id": "kill.orsino.personality.cheerful.onKill.0",
      "when": {
        "manner": "cheerful",
        "side": "company"
      },
      "text": "{Actor} grins: ‘Got 'em!’",
      "source": {
        "orsino": "barks:personality.cheerful.onKill"
      }
    },
    {
      "id": "crit.orsino.personality.cheerful.onCrit.0",
      "when": {
        "manner": "cheerful",
        "side": "company"
      },
      "text": "{Actor} laughs: ‘How about that?’",
      "source": {
        "orsino": "barks:personality.cheerful.onCrit"
      }
    },
    {
      "id": "miss.orsino.personality.cheerful.onMiss.0",
      "when": {
        "manner": "cheerful",
        "side": "company"
      },
      "text": "{Actor} chuckles: ‘Almost had 'em!’",
      "source": {
        "orsino": "barks:personality.cheerful.onMiss"
      }
    },
    {
      "id": "kill.orsino.personality.acerbic.onKill.0",
      "when": {
        "manner": "acerbic",
        "side": "company"
      },
      "text": "{Actor} sneers: ‘Pathetic.’",
      "source": {
        "orsino": "barks:personality.acerbic.onKill"
      }
    },
    {
      "id": "crit.orsino.personality.acerbic.onCrit.0",
      "when": {
        "manner": "acerbic",
        "side": "company"
      },
      "text": "{Actor} mutters sarcastically: ‘Impressive. For them.’",
      "source": {
        "orsino": "barks:personality.acerbic.onCrit"
      }
    },
    {
      "id": "fall.orsino.personality.acerbic.onFall.0",
      "when": {
        "manner": "acerbic",
        "side": "company"
      },
      "text": "{Actor} sighs: ‘Of course.’",
      "source": {
        "orsino": "barks:personality.acerbic.onFall"
      }
    },
    {
      "id": "kill.orsino.personality.compassionate.onKill.0",
      "when": {
        "manner": "compassionate",
        "side": "company"
      },
      "text": "{Actor} looks away solemnly.",
      "source": {
        "orsino": "barks:personality.compassionate.onKill"
      }
    },
    {
      "id": "crit.orsino.personality.compassionate.onCrit.0",
      "when": {
        "manner": "compassionate",
        "side": "company"
      },
      "text": "{Actor} winces: ‘I'm sorry it had to be this way.’",
      "source": {
        "orsino": "barks:personality.compassionate.onCrit"
      }
    },
    {
      "id": "kill.orsino.personality.stoic.onKill.0",
      "when": {
        "manner": "stoic",
        "side": "company"
      },
      "text": "{Actor} nods slightly.",
      "source": {
        "orsino": "barks:personality.stoic.onKill"
      }
    },
    {
      "id": "crit.orsino.personality.stoic.onCrit.0",
      "when": {
        "manner": "stoic",
        "side": "company"
      },
      "text": "{Actor} remains expressionless.",
      "source": {
        "orsino": "barks:personality.stoic.onCrit"
      }
    },
    {
      "id": "fall.orsino.personality.stoic.onFall.0",
      "when": {
        "manner": "stoic",
        "side": "company"
      },
      "text": "{Actor} accepts their fate with quiet dignity.",
      "source": {
        "orsino": "barks:personality.stoic.onFall"
      }
    },
    {
      "id": "kill.orsino.personality.jovial.onKill.0",
      "when": {
        "manner": "jovial",
        "side": "company"
      },
      "text": "{Actor} chuckles: ‘That was fun!’",
      "source": {
        "orsino": "barks:personality.jovial.onKill"
      }
    },
    {
      "id": "crit.orsino.personality.jovial.onCrit.0",
      "when": {
        "manner": "jovial",
        "side": "company"
      },
      "text": "{Actor} laughs heartily: ‘Bullseye!’",
      "source": {
        "orsino": "barks:personality.jovial.onCrit"
      }
    },
    {
      "id": "dodge.orsino.personality.jovial.onMissReceived.0",
      "when": {
        "manner": "jovial",
        "side": "company"
      },
      "text": "{Actor} grins: ‘You'll have to do better than that!’",
      "source": {
        "orsino": "barks:personality.jovial.onMissReceived"
      }
    },
    {
      "id": "engage.orsino.npc.Novice.onEngage.0",
      "when": {
        "role": "novice"
      },
      "text": "{Actor} shouts: ‘I, {actor}, will protect the sacred grounds!’",
      "source": {
        "orsino": "barks:npc.Novice.onEngage"
      }
    },
    {
      "id": "engage.orsino.npc.Novice.onEngage.1",
      "when": {
        "role": "novice"
      },
      "text": "{Actor} nervously whines: ‘Please, don't harm me! It's my first day!’",
      "source": {
        "orsino": "barks:npc.Novice.onEngage"
      }
    },
    {
      "id": "crit.orsino.npc.Novice.onCrit.0",
      "when": {
        "role": "novice"
      },
      "text": "{Actor} shouts: ‘Take that!’",
      "source": {
        "orsino": "barks:npc.Novice.onCrit"
      }
    },
    {
      "id": "crit.orsino.npc.Novice.onCrit.1",
      "when": {
        "role": "novice"
      },
      "text": "{Actor} yells: ‘You'll regret coming here!’",
      "source": {
        "orsino": "barks:npc.Novice.onCrit"
      }
    },
    {
      "id": "crit.orsino.npc.Novice.onCrit.2",
      "when": {
        "role": "novice"
      },
      "text": "{Actor} shouts: ‘For the temple!’",
      "source": {
        "orsino": "barks:npc.Novice.onCrit"
      }
    },
    {
      "id": "hurt.orsino.npc.Novice.onHitReceived.0",
      "when": {
        "role": "novice"
      },
      "text": "{Actor} cries out in pain!",
      "source": {
        "orsino": "barks:npc.Novice.onHitReceived"
      }
    },
    {
      "id": "hurt.orsino.npc.Novice.onHitReceived.1",
      "when": {
        "role": "novice"
      },
      "text": "{Actor} stammers: ‘You'll pay for that!’",
      "source": {
        "orsino": "barks:npc.Novice.onHitReceived"
      }
    },
    {
      "id": "fall.orsino.npc.Novice.onFall.0",
      "when": {
        "role": "novice"
      },
      "text": "{Actor} gasps: ‘I... I can't go on...’",
      "source": {
        "orsino": "barks:npc.Novice.onFall"
      }
    },
    {
      "id": "fall.orsino.npc.Novice.onFall.1",
      "when": {
        "role": "novice"
      },
      "text": "{Actor} pleads: ‘Mercy... please...’",
      "source": {
        "orsino": "barks:npc.Novice.onFall"
      }
    },
    {
      "id": "fall.orsino.npc.Novice.onFall.2",
      "when": {
        "role": "novice"
      },
      "text": "{Actor} collapses: ‘Tell... the Master...’",
      "source": {
        "orsino": "barks:npc.Novice.onFall"
      }
    },
    {
      "id": "fall.orsino.npc.Novice.onFall.3",
      "when": {
        "role": "novice"
      },
      "text": "{Actor} falls silent, their eyes glazing over.",
      "source": {
        "orsino": "barks:npc.Novice.onFall"
      }
    },
    {
      "id": "flee.orsino.npc.Novice.onFlee.0",
      "when": {
        "role": "novice"
      },
      "text": "‘Retreat! Retreat!’, shouts {actor}.",
      "source": {
